import { runServer } from "./runtime.js";
import { MissingHevyApiKeyError } from "./utils/config.js";
import { createSafeErrorDiagnostic } from "@hevy-mcp/core";
import { flushTelemetry } from "./utils/telemetry.js";

void runServer().catch(async (error) => {
	if (error instanceof MissingHevyApiKeyError) {
		console.error(error.message);
	} else {
		console.error("Fatal error in main()", createSafeErrorDiagnostic(error));
	}
	try {
		await flushTelemetry();
	} catch {
		// Preserve the original fatal exit when telemetry flushing fails.
	}
	process.exit(1);
});

import { createHevyMcpServer } from "@hevy-mcp/core";
import { createHevyClient } from "@hevy-mcp/hevy-client";
import { z } from "zod";
import type { NodeTransport } from "./utils/arguments.js";

const serverConfigSchema = z.object({
	apiKey: z
		.string()
		.min(1, "Hevy API key is required")
		.describe("Your Hevy API key (available in the Hevy app settings)."),
});

/**
 * Create an unconnected MCP server for embedding in a Node application.
 *
 * This entry point intentionally contains no Node runtime bootstrap. It does
 * not read process state, probe Hevy, install process handlers, initialize
 * telemetry, or connect a transport. The embedding application owns those
 * concerns and the transport lifecycle.
 */
export function createNodeMcpServer(
	{ apiKey }: { apiKey: string },
	_transport: NodeTransport = "stdio",
	lifecycleSignal?: AbortSignal,
) {
	try {
		const { apiKey: validatedApiKey } = serverConfigSchema.parse({ apiKey });
		return Promise.resolve(
			createHevyMcpServer({
				createClient: ({ onLog }) =>
					createHevyClient({
						apiKey: validatedApiKey,
						onLog,
					}),
				lifecycleSignal,
			}),
		);
	} catch (error) {
		return Promise.reject(error);
	}
}

/**
 * Compatibility wrapper for the executable runtime. Importing this module
 * does not evaluate the runtime bootstrap; it is loaded only when invoked.
 */
export async function runStdioServer(): Promise<void> {
	const { runStdioServer: run } = await import("./runtime.js");
	return run();
}

/**
 * Compatibility wrapper for the executable runtime. Importing this module
 * does not evaluate the runtime bootstrap; it is loaded only when invoked.
 */
export async function runServer(): Promise<void> {
	const { runServer: run } = await import("./runtime.js");
	return run();
}

// Telemetry must be initialized before any other imports so that
// OpenTelemetry and Sentry are ready before application code runs.
import { tracer, serviceName, serviceVersion } from "./utils/telemetry.js";
import { StdioServerTransport } from "@modelcontextprotocol/server/stdio";
import { SpanStatusCode } from "@opentelemetry/api";
import { z } from "zod";
import { createHevyMcpServer, mergeAbortSignals } from "@hevy-mcp/core";
import { createHevyClient, isHevyHttpError } from "@hevy-mcp/hevy-client";
import { assertApiKey, parseConfig } from "./utils/config.js";
import { parseNodeCliOptions, type NodeTransport } from "./utils/arguments.js";
import { startStreamableHttpServer } from "./utils/streamable-http.js";
import {
	createNodeCacheObserver,
	createNodeHevyClientOptions,
} from "./utils/hevy-client-observability.js";
import { createNodeToolObserver } from "./utils/tool-observer.js";
import { createNodeUserHash } from "./utils/user-hash.js";
import { createInstrumentedStdioTransport } from "./utils/stdio-observability.js";
import {
	recordMcpSessionTermination,
	resolveSessionTerminationCategory,
} from "./utils/mcp-session-observability.js";
import { installSdkErrorTracking } from "./utils/sdk-observability.js";
import {
	INVALID_API_KEY_MESSAGE,
	recordLifecycleFailure,
	runNodeLifecycle,
} from "./utils/node-lifecycle.js";

const objectSchema = z.object({}).passthrough();
const stringSchema = z.string();
const numberSchema = z.number();

function isObject<T>(value: T): value is T & object {
	return objectSchema.safeParse(value).success;
}
function isString<T>(value: T): value is T & string {
	return stringSchema.safeParse(value).success;
}
function isNumber<T>(value: T): value is T & number {
	return numberSchema.safeParse(value).success;
}
const name = serviceName;
const version = serviceVersion;

const HELP_TEXT = [
	"Usage:",
	"  hevy-mcp [options]",
	"",
	"Options:",
	"  -h, --help                 Show this help message and exit",
	"  -v, --version              Show version and exit",
	"  --transport stdio|http     Select the transport (default: stdio)",
	"  --host <host>              HTTP bind host (default: 127.0.0.1)",
	"  --port <port>              HTTP bind port (default: 3000)",
	"",
	"Environment:",
	"  HEVY_API_KEY=<api-key>     Hevy API key from Hevy app settings",
	"  HEVY_MCP_DEBUG=1           Enable verbose diagnostics on stderr",
	"  HEVY_MCP_HTTP_BEARER_TOKEN Protect non-loopback HTTP deployments",
	"  HEVY_MCP_TELEMETRY=0     Disable all project telemetry",
	"  HEVY_MCP_TELEMETRY_DIAGNOSTICS=0  Suppress exception details",
	"",
	"Examples:",
	"  HEVY_API_KEY=your-key npx hevy-mcp",
	"  HEVY_API_KEY=your-key npx hevy-mcp --transport http --port 3000",
].join("\n");

function getCliAction(args: string[]): "start" | "version" | "help" {
	for (const arg of args) {
		if (arg === "--version" || arg === "-v") {
			return "version";
		}

		if (arg === "--help" || arg === "-h") {
			return "help";
		}
	}

	return "start";
}

const HEVY_API_BASEURL = "https://api.hevyapp.com";
const STARTUP_PROBE_TIMEOUT_MS = 5_000;

const API_KEY_VALIDATION_WARNING =
	"Warning: HEVY_API_KEY could not be validated during startup. Startup will continue; check your network connection and Hevy API availability.";
const SAFE_NETWORK_ERROR_CODES = new Set([
	"EAI_AGAIN",
	"ECONNABORTED",
	"ECONNREFUSED",
	"ECONNRESET",
	"ENETUNREACH",
	"ENOTFOUND",
	"ERR_NETWORK",
	"ERR_SOCKET_TIMEOUT",
	"ETIMEDOUT",
	"HEVY_RETRY_EXHAUSTED",
]);

const serverConfigSchema = z.object({
	apiKey: z
		.string()
		.min(1, "Hevy API key is required")
		.describe("Your Hevy API key (available in the Hevy app settings)."),
});
const validationErrorDetailsSchema = z.object({
	response: z.object({ status: z.number().optional() }).optional(),
	code: z.string().optional(),
});
const validationErrorSchema = z.union([
	z.instanceof(Error),
	z.string(),
	validationErrorDetailsSchema,
]);
type ValidationError = z.infer<typeof validationErrorSchema>;

function getHttpStatus(error: ValidationError): number | undefined {
	if (isHevyHttpError(error)) {
		return error.status;
	}
	if (!error || !isObject(error) || !("response" in error)) {
		return undefined;
	}

	const response = error.response;
	if (!response || !isObject(response) || !("status" in response)) {
		return undefined;
	}

	return isNumber(response.status) &&
		Number.isInteger(response.status) &&
		response.status >= 100 &&
		response.status <= 599
		? response.status
		: undefined;
}

function getSafeValidationDiagnostic(
	error: ValidationError,
): string | undefined {
	const status = getHttpStatus(error);
	if (status !== undefined) {
		return `HTTP ${status}`;
	}

	if (!error || !isObject(error) || !("code" in error)) {
		return undefined;
	}

	const code = error.code;
	return isString(code) && SAFE_NETWORK_ERROR_CODES.has(code)
		? code
		: undefined;
}
async function validateApiKey(apiKey: string, signal?: AbortSignal) {
	// Keep the startup probe separate from the normal MCP-aware client. The
	// server is not connected yet, so structured client logging is intentionally
	// omitted until the normal client is built below.
	const startupProbeClient = createHevyClient({
		apiKey,
		baseUrl: HEVY_API_BASEURL,
		maxGetRetries: 0,
		timeoutMs: STARTUP_PROBE_TIMEOUT_MS,
	});

	try {
		await startupProbeClient.getUserInfo({
			signal,
			deadline: Date.now() + STARTUP_PROBE_TIMEOUT_MS,
		});
	} catch (caughtError) {
		const parsedError = validationErrorSchema.safeParse(caughtError);
		const error: ValidationError = isHevyHttpError(caughtError)
			? caughtError
			: parsedError.success
				? parsedError.data
				: String(caughtError);
		if (signal?.aborted) throw error;
		const status = getHttpStatus(error);
		if (status === 401 || status === 403) {
			throw new Error(INVALID_API_KEY_MESSAGE);
		}

		const diagnostic = getSafeValidationDiagnostic(error);
		console.error(
			diagnostic
				? `${API_KEY_VALIDATION_WARNING} Diagnostic: ${diagnostic}.`
				: API_KEY_VALIDATION_WARNING,
		);
	}
}

function buildServer(
	apiKey: string,
	transport: NodeTransport = "stdio",
	lifecycleSignal?: AbortSignal,
) {
	return tracer.startActiveSpan(
		"mcp.server.build",
		{
			attributes: {
				"mcp.span.category": "startup",
				"mcp.server.name": name,
				"mcp.server.version": version,
				"mcp.transport": transport,
			},
		},
		(span) => {
			try {
				const server = createHevyMcpServer({
					createClient: ({ onLog }) =>
						createHevyClient({
							apiKey,
							...createNodeHevyClientOptions(),
							onLog,
						}),
					lifecycleSignal,
					onToolsRegistered: (count) =>
						span.setAttribute("mcp.tools.count", count),
					observer: createNodeToolObserver({
						userHash: createNodeUserHash(apiKey),
					}),
					cacheObserver: createNodeCacheObserver(),
				});
				installSdkErrorTracking(server, transport);
				console.error("Hevy client initialized with API key");

				span.setStatus({ code: SpanStatusCode.OK });
				return server;
			} catch (caughtError) {
				const e =
					caughtError instanceof Error ? caughtError : String(caughtError);
				recordLifecycleFailure(span, e, "build", "startup_failure");
				span.setStatus({ code: SpanStatusCode.ERROR });
				throw e;
			} finally {
				span.end();
			}
		},
	);
}

export async function createNodeMcpServer(
	{ apiKey }: { apiKey: string },
	transport: NodeTransport = "stdio",
	lifecycleSignal?: AbortSignal,
) {
	const { apiKey: validatedApiKey } = serverConfigSchema.parse({ apiKey });
	await validateApiKey(validatedApiKey, lifecycleSignal);
	return buildServer(validatedApiKey, transport, lifecycleSignal);
}

export async function runStdioServer() {
	const args = process.argv.slice(2);
	const cliAction = getCliAction(args);

	if (cliAction === "version") {
		console.error(`${name} v${version}`);
		return;
	}
	if (cliAction === "help") {
		console.log(HELP_TEXT);
		return;
	}

	await runNodeLifecycle({
		transport: "stdio",
		start: async (context) => {
			const { signal } = context;
			const cfg = parseConfig(process.env);
			const apiKey = cfg.apiKey;
			assertApiKey(apiKey);
			const server = await createNodeMcpServer({ apiKey }, "stdio", signal);
			console.error("Starting MCP server in stdio mode");
			const transport = createInstrumentedStdioTransport(
				new StdioServerTransport(),
			);
			context.markConnectAttempted();
			await tracer.startActiveSpan(
				"mcp.server.connect",
				{
					attributes: {
						"mcp.span.category": "session",
						"mcp.transport": "stdio",
					},
				},
				async (connectSpan) => {
					try {
						await server.connect(transport);
						context.markConnectSucceeded();
						connectSpan.setStatus({ code: SpanStatusCode.OK });
					} catch (caughtError) {
						const error =
							caughtError instanceof Error ? caughtError : String(caughtError);
						recordLifecycleFailure(
							connectSpan,
							error,
							"connect",
							"connect_failure",
						);
						connectSpan.setStatus({ code: SpanStatusCode.ERROR });
						throw error;
					} finally {
						connectSpan.end();
					}
				},
			);
			return {
				target: server,
				onShutdown: (succeeded) =>
					recordMcpSessionTermination(
						resolveSessionTerminationCategory(succeeded),
					),
			};
		},
		onFailure: (reason, outcome) => {
			if (outcome.transport === "stdio") {
				recordMcpSessionTermination(reason);
			}
		},
	});
}

export async function runServer(): Promise<void> {
	const args = process.argv.slice(2);
	const cliAction = getCliAction(args);
	if (cliAction === "version") {
		console.error(`${name} v${version}`);
		return;
	}
	if (cliAction === "help") {
		console.log(HELP_TEXT);
		return;
	}

	const options = parseNodeCliOptions(args);
	if (options.transport === "stdio") {
		await runStdioServer();
		return;
	}

	await runNodeLifecycle({
		transport: "http",
		start: async (context) => {
			const { signal } = context;
			const cfg = parseConfig(process.env);
			assertApiKey(cfg.apiKey);
			await validateApiKey(cfg.apiKey, signal);
			const handle = await startStreamableHttpServer(
				options,
				cfg.apiKey,
				(params) =>
					Promise.resolve(
						buildServer(
							params.apiKey,
							"http",
							mergeAbortSignals(signal, params.lifecycleSignal),
						),
					),
			);
			context.markListening();
			console.error(
				`Starting MCP server in HTTP mode at ${options.host}:${options.port}/mcp`,
			);
			return { target: handle };
		},
		onFailure: (_reason, outcome) => {
			if (outcome.transport === "http") {
				recordMcpSessionTermination(
					outcome.listening ? "unknown" : "startup_failure",
				);
			}
		},
	});
}

import { SpanStatusCode, type Span } from "@opentelemetry/api";
import {
	serviceName,
	serviceVersion,
	tracer,
	captureFailure,
	flushTelemetry,
	installProcessExceptionTracking,
} from "./telemetry.js";
import { serverStartups } from "./metrics.js";
import { installGracefulShutdown } from "./graceful-shutdown.js";
import { scheduleUpdateCheck } from "./version-check.js";
import { MissingHevyApiKeyError } from "./config.js";
import type { FailureContext } from "./failure-reporter.js";
export const INVALID_API_KEY_MESSAGE =
	"HEVY_API_KEY is invalid or expired. Please check your API key in the Hevy app under Settings > API Key.";

type LifecycleFailurePhase =
	| "config"
	| "api_key_validation"
	| "build"
	| "connect"
	| "run";

type LifecycleTerminationReason =
	| "connect_failure"
	| "runtime_failure"
	| "startup_failure";

const LIFECYCLE_FAILURE_TAXONOMY = {
	config: {
		errorType: "MCP_SERVER_CONFIG_ERROR",
		errorCategory: "McpServerConfigFailure",
	},
	api_key_validation: {
		errorType: "MCP_API_KEY_VALIDATION_ERROR",
		errorCategory: "McpApiKeyValidationFailure",
	},
	build: {
		errorType: "MCP_SERVER_BUILD_ERROR",
		errorCategory: "McpServerBuildFailure",
	},
	connect: {
		errorType: "MCP_TRANSPORT_CONNECT_ERROR",
		errorCategory: "McpTransportConnectFailure",
	},
	run: {
		errorType: "MCP_SERVER_RUN_ERROR",
		errorCategory: "McpServerRunFailure",
	},
} satisfies Record<
	LifecycleFailurePhase,
	{ errorType: string; errorCategory: string }
>;

function isExpectedLifecycleFailure(error: Error | string): boolean {
	return (
		error instanceof MissingHevyApiKeyError ||
		(error instanceof Error && error.message === INVALID_API_KEY_MESSAGE)
	);
}

function createLifecycleFailureAttributes(
	phase: LifecycleFailurePhase,
	terminationReason: LifecycleTerminationReason,
) {
	const taxonomy = LIFECYCLE_FAILURE_TAXONOMY[phase];
	return {
		"mcp.failure.phase": phase,
		"mcp.termination.reason": terminationReason,
		"error.type": taxonomy.errorType,
		"error.category": taxonomy.errorCategory,
	};
}

export function recordLifecycleFailure(
	span: Span,
	error: Error | string,
	phase: LifecycleFailurePhase,
	terminationReason: LifecycleTerminationReason,
): void {
	const attributes = createLifecycleFailureAttributes(phase, terminationReason);
	span.addEvent("mcp.lifecycle.failure", attributes);
	const failure = {
		kind: "lifecycle",
		attributes,
		span,
	} satisfies FailureContext;
	captureFailure(
		error,
		isExpectedLifecycleFailure(error)
			? { ...failure, expected: true }
			: failure,
	);
}

export type NodeLifecycleTransport = "stdio" | "http";

export interface NodeLifecycleContext {
	readonly signal: AbortSignal;
	/** Mark the beginning of a stdio transport connection attempt. */
	markConnectAttempted(): void;
	/** Mark a successful stdio transport connection. */
	markConnectSucceeded(): void;
	/** Mark the HTTP listener as successfully started. */
	markListening(): void;
}

export type NodeLifecycleOutcome =
	| {
			transport: "stdio";
			connectAttempted: boolean;
			connectSucceeded: boolean;
	  }
	| {
			transport: "http";
			listening: boolean;
	  };

export interface NodeLifecycleStartupResult {
	target: { close(): Promise<void> };
	onShutdown?: (succeeded: boolean) => void | Promise<void>;
}

export interface RunNodeLifecycleOptions {
	transport: NodeLifecycleTransport;
	readonly start: (
		context: NodeLifecycleContext,
	) => Promise<NodeLifecycleStartupResult>;
	readonly onFailure?: (
		reason: LifecycleTerminationReason,
		outcome: NodeLifecycleOutcome,
	) => void;
}

function createOutcomeState(transport: NodeLifecycleTransport) {
	let connectAttempted = false;
	let connectSucceeded = false;
	let listening = false;
	return {
		markConnectAttempted: () => {
			connectAttempted = true;
		},
		markConnectSucceeded: () => {
			connectSucceeded = true;
		},
		markListening: () => {
			listening = true;
		},
		getOutcome: (): NodeLifecycleOutcome =>
			transport === "stdio"
				? { transport, connectAttempted, connectSucceeded }
				: { transport, listening },
	};
}

function classifyFailure(
	outcome: NodeLifecycleOutcome,
): LifecycleTerminationReason {
	if (outcome.transport === "stdio") {
		if (outcome.connectAttempted && !outcome.connectSucceeded) {
			return "connect_failure";
		}
		return outcome.connectSucceeded ? "runtime_failure" : "startup_failure";
	}
	return outcome.listening ? "runtime_failure" : "startup_failure";
}

/** Owns process-wide Node lifecycle concerns while leaving transport state local. */
export async function runNodeLifecycle({
	transport,
	start,
	onFailure,
}: RunNodeLifecycleOptions): Promise<void> {
	const cleanupProcessExceptionTracking = installProcessExceptionTracking();
	const lifecycleController = new AbortController();
	const state = createOutcomeState(transport);
	const context: NodeLifecycleContext = {
		signal: lifecycleController.signal,
		markConnectAttempted: () => state.markConnectAttempted(),
		markConnectSucceeded: () => state.markConnectSucceeded(),
		markListening: () => state.markListening(),
	};

	serverStartups.add(1, { version: serviceVersion });
	await tracer.startActiveSpan(
		"mcp.server.run",
		{
			attributes: {
				"mcp.span.category": "startup",
				"mcp.transport": transport,
			},
		},
		async (span) => {
			try {
				const result = await start(context);
				scheduleUpdateCheck({
					packageName: serviceName,
					currentVersion: serviceVersion,
				});
				installGracefulShutdown({
					target: result.target,
					cancel: lifecycleController,
					onComplete: async (succeeded) => {
						try {
							await result.onShutdown?.(succeeded);
						} finally {
							cleanupProcessExceptionTracking();
							await flushTelemetry();
						}
					},
				});
				span.setStatus({ code: SpanStatusCode.OK });
			} catch (error) {
				const outcome = state.getOutcome();
				const reason = classifyFailure(outcome);
				// A failed stdio connect already has its own connect span. Preserve
				// that taxonomy and only record the common run failure otherwise.
				if (!(outcome.transport === "stdio" && reason === "connect_failure")) {
					recordLifecycleFailure(
						span,
						error instanceof Error ? error : String(error),
						"run",
						reason,
					);
				}
				onFailure?.(reason, outcome);
				span.setStatus({ code: SpanStatusCode.ERROR });
				cleanupProcessExceptionTracking();
				throw error;
			} finally {
				span.end();
			}
		},
	);
}

export type { LifecycleFailurePhase, LifecycleTerminationReason };

export type ShutdownSignal = "SIGINT" | "SIGTERM";

interface CloseTarget {
	close(): Promise<void>;
}

interface ProcessLike {
	exitCode?: number | string | null;
	exit(code?: number | string | null): never;
	on(signal: ShutdownSignal, listener: () => void): unknown;
	removeListener(signal: ShutdownSignal, listener: () => void): unknown;
}

interface FlushableStdout {
	write(chunk: string, callback: (error?: Error | null) => void): boolean;
}

interface ForcedExitTimer {
	unref(): void;
}

type ScheduleForcedExit = (
	callback: () => void,
	timeoutMs: number,
) => ForcedExitTimer;

interface GracefulShutdownOptions {
	target: CloseTarget;
	process?: ProcessLike;
	logError?: (message: string) => void;
	flush?: () => Promise<void>;
	forcedExitTimeoutMs?: number;
	onComplete?: (succeeded: boolean) => void | Promise<void>;
	scheduleForcedExit?: ScheduleForcedExit;
	cancel?: AbortController;
}

export interface GracefulShutdownController {
	cleanup(): void;
	getShutdownPromise(): Promise<void> | undefined;
}

const shutdownSignals: ShutdownSignal[] = ["SIGINT", "SIGTERM"];

// Long enough for normal stdio flushing, but bounded so unrelated handles or a
// stalled close cannot keep a signal-terminated process alive indefinitely.
export const FORCED_EXIT_TIMEOUT_MS = 5_000;

export function flushStdout(
	stdout: FlushableStdout = process.stdout,
): Promise<void> {
	return new Promise((resolve, reject) => {
		try {
			stdout.write("", (error) => {
				if (error) {
					reject(error);
					return;
				}

				resolve();
			});
		} catch (error) {
			reject(error);
		}
	});
}

export function installGracefulShutdown({
	target,
	process: processLike = process,
	logError = console.error,
	flush = flushStdout,
	forcedExitTimeoutMs = FORCED_EXIT_TIMEOUT_MS,
	scheduleForcedExit = setTimeout,
	cancel,
	onComplete,
}: GracefulShutdownOptions): GracefulShutdownController {
	let listenersInstalled = true;
	let shutdownSettled = false;
	let shutdownPromise: Promise<void> | undefined;
	let completionReported = false;

	const reportCompletion = (succeeded: boolean): Promise<void> | undefined => {
		if (completionReported) return undefined;
		completionReported = true;
		try {
			const completion = onComplete?.(succeeded);
			return completion
				? Promise.resolve(completion).catch(() => {
						logError("Graceful shutdown completion observer failed");
					})
				: undefined;
		} catch {
			logError("Graceful shutdown completion observer failed");
			return undefined;
		}
	};

	const cleanup = () => {
		if (!listenersInstalled || (shutdownPromise && !shutdownSettled)) {
			return;
		}

		listenersInstalled = false;
		for (const signal of shutdownSignals) {
			const listener = signalListeners.get(signal);
			if (listener) {
				processLike.removeListener(signal, listener);
			}
		}
	};

	const handleSignal = (signal: ShutdownSignal) => {
		if (shutdownPromise) {
			return;
		}

		if (processLike.exitCode == null) {
			processLike.exitCode = 0;
		}
		cancel?.abort(
			new DOMException(`Shutdown requested by ${signal}`, "AbortError"),
		);

		const forcedExitTimer = scheduleForcedExit(() => {
			void reportCompletion(false);
			processLike.exit(shutdownSettled ? (processLike.exitCode ?? 0) : 1);
		}, forcedExitTimeoutMs);
		// This fallback must survive successful shutdown so it can terminate a
		// process held open by unrelated handles, without keeping the process alive
		// when the event loop drains normally.
		forcedExitTimer.unref();

		shutdownPromise = (async () => {
			logError(`Shutting down gracefully after ${signal}`);
			let shutdownFailed = false;
			let shutdownError: unknown;

			try {
				await target.close();
			} catch (error) {
				shutdownFailed = true;
				shutdownError = error;
			}

			try {
				await flush();
			} catch (error) {
				if (!shutdownFailed) {
					shutdownError = error;
				}
				shutdownFailed = true;
			}

			try {
				if (shutdownFailed) {
					const message =
						shutdownError instanceof Error
							? shutdownError.message
							: "Unknown shutdown error";
					logError(`Graceful shutdown failed: ${message}`);
					processLike.exitCode = 1;
					return;
				}
			} finally {
				await reportCompletion(!shutdownFailed);
				shutdownSettled = true;
				cleanup();
			}
		})();
	};

	const signalListeners = new Map<ShutdownSignal, () => void>(
		shutdownSignals.map((signal) => [signal, () => handleSignal(signal)]),
	);

	for (const signal of shutdownSignals) {
		const listener = signalListeners.get(signal);
		if (listener) {
			processLike.on(signal, listener);
		}
	}

	return {
		cleanup,
		getShutdownPromise: () => shutdownPromise,
	};
}

import { randomUUID, timingSafeEqual } from "node:crypto";
import {
	createServer,
	type IncomingMessage,
	type Server,
	type ServerResponse,
} from "node:http";
import { NodeStreamableHTTPServerTransport } from "@modelcontextprotocol/node";
import { z } from "zod";
import {
	createExecutionProjection,
	createSafeErrorDiagnostic,
} from "@hevy-mcp/core";
import type { NodeCliOptions } from "./arguments.js";
import { httpAdmissionRejections, httpSessionEvictions } from "./metrics.js";
import {
	runWithMcpSessionContext,
	createMcpSessionContext,
	recordMcpSessionStart,
	recordMcpSessionTermination,
	resolveSessionTerminationCategory,
	type McpSessionContext,
} from "./mcp-session-observability.js";

const stringSchema = z.string();
const numberSchema = z.number();
const objectSchema = z.object({}).passthrough();

function isString<T>(value: T): value is T & string {
	return stringSchema.safeParse(value).success;
}

function isNumber<T>(value: T): value is T & number {
	return numberSchema.safeParse(value).success;
}

function isObject<T>(value: T): value is T & object {
	return objectSchema.safeParse(value).success;
}

const MCP_PATH = "/mcp";
const MAX_BODY_BYTES = 1_048_576;
const HTTP_BEARER_TOKEN = "HEVY_MCP_HTTP_BEARER_TOKEN";

const HTTP_ADMISSION_DEFAULTS = {
	maxSessions: 100,
	maxInitializing: 10,
	idleTimeoutMs: 30 * 60 * 1000,
	bodyTimeoutMs: 30 * 1000,
} as const;
const HTTP_ADMISSION_LIMITS = {
	maxSessions: 10_000,
	maxInitializing: 1_000,
	idleTimeoutMs: 24 * 60 * 60 * 1000,
	bodyTimeoutMs: 5 * 60 * 1000,
} as const;

export interface HttpAdmissionConfig {
	maxSessions: number;
	maxInitializing: number;
	idleTimeoutMs: number;
	bodyTimeoutMs: number;
}

function parsePositiveLimit<T>(
	value: T,
	fallback: number,
	maximum: number,
): number {
	const parsed = isNumber(value) ? value : Number(value);
	if (!Number.isFinite(parsed) || parsed < 1) return fallback;
	return Math.min(Math.floor(parsed), maximum);
}

function envLimit(name: string, fallback: number, maximum: number): number {
	return parsePositiveLimit(process.env[name], fallback, maximum);
}

export function resolveHttpAdmissionConfig(
	overrides: Partial<HttpAdmissionConfig> = {},
): HttpAdmissionConfig {
	return {
		maxSessions: parsePositiveLimit(
			overrides.maxSessions ??
				envLimit(
					"HEVY_MCP_HTTP_MAX_SESSIONS",
					HTTP_ADMISSION_DEFAULTS.maxSessions,
					HTTP_ADMISSION_LIMITS.maxSessions,
				),
			HTTP_ADMISSION_DEFAULTS.maxSessions,
			HTTP_ADMISSION_LIMITS.maxSessions,
		),
		maxInitializing: parsePositiveLimit(
			overrides.maxInitializing ??
				envLimit(
					"HEVY_MCP_HTTP_MAX_INITIALIZING",
					HTTP_ADMISSION_DEFAULTS.maxInitializing,
					HTTP_ADMISSION_LIMITS.maxInitializing,
				),
			HTTP_ADMISSION_DEFAULTS.maxInitializing,
			HTTP_ADMISSION_LIMITS.maxInitializing,
		),
		idleTimeoutMs: parsePositiveLimit(
			overrides.idleTimeoutMs ??
				envLimit(
					"HEVY_MCP_HTTP_IDLE_TIMEOUT_MS",
					HTTP_ADMISSION_DEFAULTS.idleTimeoutMs,
					HTTP_ADMISSION_LIMITS.idleTimeoutMs,
				),
			HTTP_ADMISSION_DEFAULTS.idleTimeoutMs,
			HTTP_ADMISSION_LIMITS.idleTimeoutMs,
		),
		bodyTimeoutMs: parsePositiveLimit(
			overrides.bodyTimeoutMs ??
				envLimit(
					"HEVY_MCP_HTTP_BODY_TIMEOUT_MS",
					HTTP_ADMISSION_DEFAULTS.bodyTimeoutMs,
					HTTP_ADMISSION_LIMITS.bodyTimeoutMs,
				),
			HTTP_ADMISSION_DEFAULTS.bodyTimeoutMs,
			HTTP_ADMISSION_LIMITS.bodyTimeoutMs,
		),
	};
}

type HttpTransport = NodeStreamableHTTPServerTransport;
export interface OwnedMcpServer {
	connect(transport: HttpTransport): Promise<void>;
	close(): Promise<void>;
}

export type McpServerFactory = (params: {
	apiKey: string;
	lifecycleSignal?: AbortSignal;
}) => Promise<OwnedMcpServer>;

interface HttpSession {
	transport: HttpTransport;
	server: OwnedMcpServer;
	context: McpSessionContext;
	lifecycleController: AbortController;
	responses: Set<ServerResponse>;
	idleTimer?: ReturnType<typeof setTimeout>;
	closed: boolean;
}

export interface HttpServerHandle {
	close(): Promise<void>;
	server: Server;
}

class HttpRequestError extends Error {
	readonly statusCode: number;

	constructor(statusCode: number, message: string) {
		super(message);
		this.name = "HttpRequestError";
		this.statusCode = statusCode;
	}
}

function normalizeHost(host: string): string {
	return host.startsWith("[") && host.endsWith("]") ? host.slice(1, -1) : host;
}

function isLoopbackHost(host: string): boolean {
	const normalized = normalizeHost(host).toLowerCase();
	return (
		normalized === "localhost" ||
		normalized === "127.0.0.1" ||
		normalized === "::1"
	);
}

function hostNamesFor(options: NodeCliOptions): Set<string> {
	const configured = normalizeHost(options.host).toLowerCase();
	const names = new Set([configured]);
	if (isLoopbackHost(options.host)) {
		names.add("localhost");
		names.add("127.0.0.1");
		names.add("::1");
	}
	return names;
}

function expectedPort(options: NodeCliOptions, server: Server): number {
	if (options.port !== 0) return options.port;
	const address = server.address();
	return address && !isString(address) ? address.port : 0;
}

function validateHostHeader(
	request: IncomingMessage,
	allowedHosts: Set<string>,
	port: number,
	allowAnyHostname = false,
): boolean {
	const header = request.headers.host;
	if (!header || Array.isArray(header)) return false;
	try {
		const parsed = new URL(`http://${header}`);
		if (
			parsed.username ||
			parsed.password ||
			parsed.pathname !== "/" ||
			parsed.search ||
			parsed.hash ||
			(!allowAnyHostname && (parsed.port ? Number(parsed.port) : 80) !== port)
		) {
			return false;
		}
		return (
			allowAnyHostname ||
			allowedHosts.has(normalizeHost(parsed.hostname).toLowerCase())
		);
	} catch {
		return false;
	}
}

function safeDiagnostic<T>(error: T): string {
	return JSON.stringify(createSafeErrorDiagnostic(error));
}

function writeJson(res: ServerResponse, status: number, message: string): void {
	if (res.headersSent || res.destroyed) return;
	res.statusCode = status;
	res.setHeader("Content-Type", "application/json");
	res.end(JSON.stringify({ error: message }));
}

function writeExecutionJson<T>(
	res: ServerResponse,
	status: number,
	message: string,
	error: T,
): void {
	if (res.headersSent || res.destroyed) return;
	const diagnostic = createSafeErrorDiagnostic(error);
	const execution = createExecutionProjection(diagnostic);
	res.statusCode = status;
	res.setHeader("Content-Type", "application/json");
	res.end(
		JSON.stringify({
			error: { message, ...execution },
		}),
	);
}

interface ReadBodyHandlers {
	onData: (chunk: Buffer | string) => void;
	onError: (error: Error) => void;
	onAbort: () => void;
	onEnd: () => void;
	onTimeout: () => void;
}

interface RejectBeforeBodyHandlers {
	onError: () => void;
}

function readBody(
	request: IncomingMessage,
	timeoutMs: number,
	signal?: AbortSignal,
): Promise<unknown> {
	return new Promise((resolve, reject) => {
		let size = 0;
		let settled = false;
		const chunks: Buffer[] = [];
		const handlers: ReadBodyHandlers = {
			onData: () => {},
			onError: () => {},
			onAbort: () => {},
			onEnd: () => {},
			onTimeout: () => {},
		};
		const timer = setTimeout(() => handlers.onTimeout(), timeoutMs);
		const removeErrorListenerAfterDrain = () => {
			request.removeListener("error", handlers.onError);
		};
		const cleanup = (retainErrorListener = false) => {
			clearTimeout(timer);
			request.removeListener("data", handlers.onData);
			request.removeListener("end", handlers.onEnd);
			if (retainErrorListener) {
				request.once("close", removeErrorListenerAfterDrain);
			} else {
				request.removeListener("error", handlers.onError);
			}
			signal?.removeEventListener("abort", handlers.onAbort);
		};
		const settle = (callback: () => void, retainErrorListener = false) => {
			if (settled) return;
			settled = true;
			cleanup(retainErrorListener);
			callback();
		};
		const rejectAndDrain = (error: HttpRequestError) => {
			if (settled) return;
			settled = true;
			cleanup(true);
			request.resume();
			reject(error);
		};
		handlers.onData = (chunk: Buffer | string) => {
			const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
			size += buffer.byteLength;
			if (size > MAX_BODY_BYTES) {
				rejectAndDrain(new HttpRequestError(413, "Request body is too large."));
				return;
			}
			if (!settled) chunks.push(buffer);
		};
		handlers.onError = (error: Error) => settle(() => reject(error));
		handlers.onAbort = () =>
			rejectAndDrain(
				new HttpRequestError(
					503,
					"HTTP server is shutting down. Retry shortly.",
				),
			);
		handlers.onEnd = () =>
			settle(() => {
				try {
					const raw = Buffer.concat(chunks).toString("utf8");
					resolve(raw.length === 0 ? undefined : JSON.parse(raw));
				} catch {
					reject(new HttpRequestError(400, "Request body must be valid JSON."));
				}
			});
		handlers.onTimeout = () =>
			rejectAndDrain(new HttpRequestError(408, "Request body timed out."));
		request.on("data", handlers.onData);
		request.once("error", handlers.onError);
		request.once("end", handlers.onEnd);
		signal?.addEventListener("abort", handlers.onAbort, { once: true });
		timer.unref?.();
		if (signal?.aborted) handlers.onAbort();
	});
}

function isInitializeRequest<T>(body: T): boolean {
	return Boolean(
		body &&
		isObject(body) &&
		!Array.isArray(body) &&
		"method" in body &&
		body.method === "initialize",
	);
}

function closeServer(server: Server): Promise<void> {
	return new Promise((resolve, reject) => {
		if (!server.listening) {
			resolve();
			return;
		}
		server.close((error) => (error ? reject(error) : resolve()));
		server.closeIdleConnections();
		server.closeAllConnections();
	});
}

function isBearerAuthorized(
	request: IncomingMessage,
	token: string | undefined,
): boolean {
	if (!token) return false;
	const header = request.headers.authorization;
	if (!isString(header)) return false;
	const expected = Buffer.from(`Bearer ${token}`);
	const actual = Buffer.from(header);
	return (
		expected.byteLength === actual.byteLength &&
		timingSafeEqual(expected, actual)
	);
}

function aggregateErrors<T>(errors: T[], message: string): T | AggregateError {
	if (errors.length === 1) return errors[0];
	return new AggregateError(errors, message);
}

function recordHttpAdmissionRejection(
	reason: "shutting_down" | "initializing_capacity" | "session_capacity",
): void {
	try {
		httpAdmissionRejections.add(1, { reason });
	} catch {
		// Optional telemetry must never affect admission behavior.
	}
}

function recordHttpSessionEviction(): void {
	try {
		httpSessionEvictions.add(1, { reason: "idle" });
	} catch {
		// Optional telemetry must never affect cleanup behavior.
	}
}

function rejectBeforeBody(
	request: IncomingMessage,
	response: ServerResponse,
	status: number,
	message: string,
	timeoutMs: number,
): void {
	const handlers: RejectBeforeBodyHandlers = { onError: () => {} };
	const timer = setTimeout(() => request.destroy(), timeoutMs);
	const cleanup = () => {
		clearTimeout(timer);
		request.removeListener("error", handlers.onError);
		request.removeListener("close", cleanup);
	};
	handlers.onError = () => cleanup();
	request.once("error", handlers.onError);
	request.once("close", cleanup);
	timer.unref?.();
	request.resume();
	writeJson(response, status, message);
}

export function isHttpHostAllowed(host: string): boolean {
	return isLoopbackHost(host);
}

export async function startStreamableHttpServer(
	options: NodeCliOptions,
	apiKey: string,
	createMcpServer: McpServerFactory,
	configOverrides: Partial<HttpAdmissionConfig> = {},
): Promise<HttpServerHandle> {
	const config = resolveHttpAdmissionConfig(configOverrides);
	const wildcard =
		options.host === "0.0.0.0" ||
		options.host === "::" ||
		options.host === "[::]";
	const loopback = isLoopbackHost(options.host);
	const bearerToken = process.env[HTTP_BEARER_TOKEN];
	if (!loopback && !bearerToken) {
		throw new Error(
			`Non-loopback HTTP mode requires ${HTTP_BEARER_TOKEN} to protect the shared Hevy account. Set ${HTTP_BEARER_TOKEN} to a secure random value, then retry.`,
		);
	}

	const sessions = new Map<string, HttpSession>();
	const pendingSessions = new Set<HttpSession>();
	const initializationControllers = new Set<AbortController>();
	const initializationPromises = new Set<Promise<void>>();
	const cleanupErrors: unknown[] = [];
	let shuttingDown = false;
	const server = createServer((request, response) => {
		void handleRequest(request, response).catch((error) => {
			if (response.headersSent || response.destroyed) {
				if (!response.writableEnded) response.destroy();
				return;
			}
			if (error instanceof HttpRequestError) {
				writeJson(response, error.statusCode, error.message);
				return;
			}
			console.error(`HTTP request failed: ${safeDiagnostic(error)}`);
			writeExecutionJson(response, 500, "Internal server error.", error);
		});
	});

	function armIdleTimer(session: HttpSession): void {
		if (session.closed) return;
		if (session.idleTimer) clearTimeout(session.idleTimer);
		session.idleTimer = setTimeout(() => {
			const hasActiveResponse = [...session.responses].some(
				(response) => !response.writableEnded,
			);
			if (hasActiveResponse) {
				armIdleTimer(session);
				return;
			}
			recordHttpSessionEviction();
			closeSession(session).catch((error) => {
				cleanupErrors.push(error);
			});
		}, config.idleTimeoutMs);
		session.idleTimer.unref?.();
	}

	async function closeSession(
		session: HttpSession,
		failureCategory?: "connect_failure" | "startup_failure" | "unknown",
	): Promise<void> {
		if (session.closed) return;
		session.closed = true;
		if (session.idleTimer) {
			clearTimeout(session.idleTimer);
			session.idleTimer = undefined;
		}
		pendingSessions.delete(session);
		for (const [id, current] of sessions) {
			if (current === session) sessions.delete(id);
		}
		for (const response of session.responses) {
			if (!response.writableEnded) response.destroy();
		}
		// The SDK transport closes response streams, but its stateful close path
		// does not abort the request signal already handed to MCP handlers. Abort
		// the session-owned lifecycle signal first so active Hevy calls stop too.
		session.lifecycleController.abort(
			new DOMException("MCP session closed", "AbortError"),
		);

		const results = await Promise.allSettled([
			Promise.resolve().then(() => session.transport.close()),
			Promise.resolve().then(() => session.server.close()),
		]);
		const errors = results.flatMap((result) =>
			result.status === "rejected" ? [result.reason] : [],
		);
		const succeeded = errors.length === 0;
		recordMcpSessionTermination(
			failureCategory && succeeded
				? failureCategory
				: resolveSessionTerminationCategory(succeeded, session.context),
			session.context,
		);
		if (errors.length > 0) {
			throw aggregateErrors(errors, "MCP session cleanup failed.");
		}
	}

	async function closeUnregistered(
		transport: HttpTransport,
		mcpServer: OwnedMcpServer | undefined,
	): Promise<void> {
		const results = await Promise.allSettled([
			Promise.resolve().then(() => transport.close()),
			...(mcpServer ? [Promise.resolve().then(() => mcpServer.close())] : []),
		]);
		const errors = results.flatMap((result) =>
			result.status === "rejected" ? [result.reason] : [],
		);
		if (errors.length > 0) throw aggregateErrors(errors, "MCP cleanup failed.");
		return;
	}

	function trackSessionResponse(
		session: HttpSession,
		response: ServerResponse,
	): void {
		session.responses.add(response);
		response.once("close", () => {
			session.responses.delete(response);
			// A destroyed response means the client disconnected before the
			// exchange completed. The SDK does not expose a request-scoped signal
			// for this transport, so evict and close the whole session rather than
			// leaving an aborted session reusable or poisoning future requests.
			if (!response.writableEnded && !session.closed) {
				closeSession(session).catch((error) => {
					cleanupErrors.push(error);
				});
			} else if (!session.closed) {
				armIdleTimer(session);
			}
		});
	}

	interface RequestSessionResolution {
		sessionId?: string;
		existingSession?: HttpSession;
		trackedExistingResponse: boolean;
	}

	function resolveRequestSession(
		request: IncomingMessage,
		response: ServerResponse,
	): RequestSessionResolution | undefined {
		if (request.url?.split("?", 1)[0] !== MCP_PATH) {
			writeJson(response, 404, "Not found");
			return undefined;
		}
		if (
			!validateHostHeader(
				request,
				hostNamesFor(options),
				expectedPort(options, server),
				wildcard,
			)
		) {
			writeJson(response, 403, "Invalid Host header");
			return undefined;
		}
		if (!loopback && !isBearerAuthorized(request, bearerToken)) {
			writeJson(response, 401, "Authorization required");
			return undefined;
		}

		const sessionHeader = request.headers["mcp-session-id"];
		const sessionId = isString(sessionHeader) ? sessionHeader : undefined;
		const existingSession = sessionId ? sessions.get(sessionId) : undefined;
		if (sessionId && !existingSession) {
			rejectBeforeBody(
				request,
				response,
				404,
				"Unknown Mcp-Session-Id.",
				config.bodyTimeoutMs,
			);
			return undefined;
		}
		if (existingSession && request.method !== "DELETE") {
			trackSessionResponse(existingSession, response);
			return { sessionId, existingSession, trackedExistingResponse: true };
		}
		return { sessionId, existingSession, trackedExistingResponse: false };
	}

	interface InitializationReservation {
		controller: AbortController;
		release: () => void;
	}

	function reserveInitialization(
		request: IncomingMessage,
		response: ServerResponse,
	): InitializationReservation | null {
		if (shuttingDown) {
			recordHttpAdmissionRejection("shutting_down");
			rejectBeforeBody(
				request,
				response,
				503,
				"HTTP server is shutting down. Retry shortly.",
				config.bodyTimeoutMs,
			);
			return null;
		}
		if (initializationControllers.size >= config.maxInitializing) {
			recordHttpAdmissionRejection("initializing_capacity");
			rejectBeforeBody(
				request,
				response,
				503,
				"MCP server is busy initializing sessions. Retry shortly.",
				config.bodyTimeoutMs,
			);
			return null;
		}
		if (sessions.size + initializationControllers.size >= config.maxSessions) {
			recordHttpAdmissionRejection("session_capacity");
			rejectBeforeBody(
				request,
				response,
				429,
				"MCP session capacity reached. Retry after an existing session closes.",
				config.bodyTimeoutMs,
			);
			return null;
		}

		const controller = new AbortController();
		initializationControllers.add(controller);
		let resolveInitialization!: () => void;
		const initializationComplete = new Promise<void>((resolve) => {
			resolveInitialization = resolve;
		});
		initializationPromises.add(initializationComplete);
		let released = false;
		const onResponseClose = () => {
			if (!response.writableEnded) {
				controller.abort(
					new DOMException("MCP initialization response closed", "AbortError"),
				);
			}
		};
		response.once("close", onResponseClose);
		return {
			controller,
			release: () => {
				if (released) return;
				released = true;
				response.removeListener("close", onResponseClose);
				initializationControllers.delete(controller);
				initializationPromises.delete(initializationComplete);
				resolveInitialization();
			},
		};
	}

	async function handleInitializedSession<T>(
		request: IncomingMessage,
		response: ServerResponse,
		body: T,
		reservation: InitializationReservation,
	): Promise<void> {
		const context = createMcpSessionContext(isObject(body) ? body : {}, "http");
		recordMcpSessionStart(isObject(body) ? body : {}, "http", context);
		let session: HttpSession | undefined;
		let mcpServer: OwnedMcpServer | undefined;
		let connected = false;
		const lifecycleController = reservation.controller;
		const transport = new NodeStreamableHTTPServerTransport({
			sessionIdGenerator: randomUUID,
			onsessioninitialized: (id) => {
				if (!session) return;
				if (shuttingDown || lifecycleController.signal.aborted) {
					closeSession(session).catch((error) => {
						cleanupErrors.push(error);
					});
					return;
				}
				sessions.set(id, session);
				pendingSessions.delete(session);
				initializationControllers.delete(lifecycleController);
				armIdleTimer(session);
			},
		});
		transport.onclose = () => {
			if (session) {
				closeSession(session).catch((error) => {
					cleanupErrors.push(error);
				});
			}
		};
		try {
			mcpServer = await createMcpServer({
				apiKey,
				lifecycleSignal: lifecycleController.signal,
			});
			if (shuttingDown || lifecycleController.signal.aborted) {
				await closeUnregistered(transport, mcpServer);
				recordMcpSessionTermination("startup_failure", context);
				return;
			}
			session = {
				transport,
				server: mcpServer,
				context,
				lifecycleController,
				responses: new Set(),
				closed: false,
			};
			pendingSessions.add(session);
			await mcpServer.connect(transport);
			connected = true;
			if (shuttingDown || lifecycleController.signal.aborted) {
				await closeSession(session);
				return;
			}
			trackSessionResponse(session, response);
			await runWithMcpSessionContext(context, () =>
				transport.handleRequest(request, response, body),
			);
		} catch (error) {
			lifecycleController.abort(
				new DOMException("MCP session startup failed", "AbortError"),
			);
			console.error(`HTTP session request failed: ${safeDiagnostic(error)}`);
			let cleanupError: unknown;
			try {
				if (session) {
					await closeSession(
						session,
						connected ? "unknown" : "connect_failure",
					);
				} else {
					await closeUnregistered(transport, mcpServer);
					recordMcpSessionTermination("startup_failure", context);
				}
			} catch (cleanupFailure) {
				cleanupError = cleanupFailure;
				if (!session) recordMcpSessionTermination("unknown", context);
			}
			if (cleanupError) {
				console.error(`HTTP cleanup failed: ${safeDiagnostic(cleanupError)}`);
			}
			if (!response.writableEnded && !shuttingDown)
				writeExecutionJson(response, 500, "Internal server error.", error);
		}
	}

	async function handleInitializationRequest<T>(
		request: IncomingMessage,
		response: ServerResponse,
		body: T,
		sessionId: string | undefined,
		reservation: InitializationReservation | undefined,
	): Promise<boolean> {
		if (request.method !== "POST" || !isInitializeRequest(body)) return false;
		if (sessionId) {
			writeJson(
				response,
				400,
				"Initialization must not include Mcp-Session-Id.",
			);
			return true;
		}
		if (!reservation) {
			writeJson(
				response,
				503,
				"MCP initialization capacity is unavailable. Retry shortly.",
			);
			return true;
		}
		await handleInitializedSession(request, response, body, reservation);
		return true;
	}

	async function handleExistingSessionRequest<T>(
		request: IncomingMessage,
		response: ServerResponse,
		body: T,
		sessionId: string | undefined,
		existingSession: HttpSession | undefined,
		trackedExistingResponse: boolean,
	): Promise<void> {
		if (!sessionId) {
			writeJson(response, 400, "Mcp-Session-Id header is required.");
			return;
		}
		const session = existingSession ?? sessions.get(sessionId);
		if (!session) {
			writeJson(response, 404, "Unknown Mcp-Session-Id.");
			return;
		}
		armIdleTimer(session);
		if (request.method !== "DELETE" && !trackedExistingResponse) {
			trackSessionResponse(session, response);
		}
		await runWithMcpSessionContext(session.context, () =>
			session.transport.handleRequest(request, response, body),
		);
		if (request.method === "DELETE" && !session.closed) {
			try {
				await closeSession(session);
			} catch (error) {
				cleanupErrors.push(error);
			}
		}
	}

	async function handleRequest(
		request: IncomingMessage,
		response: ServerResponse,
	): Promise<void> {
		let releaseInitialization: (() => void) | undefined;
		try {
			const resolution = resolveRequestSession(request, response);
			if (!resolution) return;
			const requiresInitialization =
				request.method === "POST" && !resolution.sessionId;
			const reservation = requiresInitialization
				? reserveInitialization(request, response)
				: undefined;
			if (requiresInitialization && !reservation) return;
			releaseInitialization = reservation?.release;
			const body =
				request.method === "POST"
					? await readBody(
							request,
							config.bodyTimeoutMs,
							reservation?.controller.signal ??
								resolution.existingSession?.lifecycleController.signal,
						)
					: undefined;
			if (shuttingDown) {
				writeJson(
					response,
					503,
					"HTTP server is shutting down. Retry shortly.",
				);
				return;
			}
			if (
				await handleInitializationRequest(
					request,
					response,
					body,
					resolution.sessionId,
					reservation ?? undefined,
				)
			)
				return;
			await handleExistingSessionRequest(
				request,
				response,
				body,
				resolution.sessionId,
				resolution.existingSession,
				resolution.trackedExistingResponse,
			);
		} finally {
			releaseInitialization?.();
		}
	}

	await new Promise<void>((resolve, reject) => {
		server.once("error", reject);
		server.listen(options.port, options.host, () => {
			server.removeListener("error", reject);
			resolve();
		});
	});

	let closePromise: Promise<void> | undefined;
	return {
		server,
		close: () => {
			if (closePromise) return closePromise;
			closePromise = (async () => {
				shuttingDown = true;
				for (const controller of initializationControllers) {
					controller.abort(
						new DOMException("HTTP server is shutting down", "AbortError"),
					);
				}
				const sessionsToClose = [
					...new Set([...sessions.values(), ...pendingSessions]),
				];
				const results = await Promise.allSettled([
					...sessionsToClose.map((session) => closeSession(session)),
					closeServer(server),
				]);
				const initializationResults = await Promise.allSettled([
					...initializationPromises,
				]);
				sessions.clear();
				pendingSessions.clear();
				const errors = [
					...cleanupErrors,
					...results.flatMap((result) =>
						result.status === "rejected" ? [result.reason] : [],
					),
					...initializationResults.flatMap((result) =>
						result.status === "rejected" ? [result.reason] : [],
					),
				];
				if (errors.length > 0) {
					throw aggregateErrors(errors, "HTTP server cleanup failed.");
				}
			})();
			return closePromise;
		},
	};
}

