};

export type ExecutionTelemetryNamespace = "span" | "metric";
type ExecutionAttributes = Record<string, string | boolean>;

/** Project either structured errors or client observations into stable OTel keys. */
export function projectExecutionAttributes(
	execution: ExecutionAttributeSource | undefined,
	namespace: ExecutionTelemetryNamespace = "span",
): ExecutionAttributes {
	if (!execution) return {};
	const prefix = namespace === "span" ? "hevy.api." : "";
	const operationSafety =
		execution.operation_safety ?? execution.operationSafety;
	const commitState = execution.commit_state ?? execution.commitState;
	const safeToRetry = execution.safe_to_retry ?? execution.safeToRetry;
	const attributes: Record<string, string | boolean> = {};
	if (execution.outcome) attributes[`${prefix}outcome`] = execution.outcome;
	if (execution.phase) attributes[`${prefix}phase`] = execution.phase;
	if (operationSafety)
		attributes[`${prefix}operation_safety`] = operationSafety;
	if (commitState) attributes[`${prefix}commit_state`] = commitState;
	if (safeToRetry !== undefined)
		attributes[`${prefix}safe_to_retry`] = safeToRetry;
	return attributes;
}

import { randomUUID } from "node:crypto";
import { createSafeErrorDiagnostic } from "@hevy-mcp/core";
import { z } from "zod";
import { isHevyHttpError } from "@hevy-mcp/hevy-client";
import * as Sentry from "@sentry/node";
import { SpanStatusCode, trace, type Span } from "@opentelemetry/api";
import type { ErrorEvent, EventHint } from "@sentry/node";

type SafeErrorDiagnostic = ReturnType<typeof createSafeErrorDiagnostic>;
type Mutable<T> = { -readonly [K in keyof T]: T[K] };
type NormalizedException = {
	name: string;
	message?: string;
	stack?: string;
};
type NormalizedFailureDraft = {
	diagnostic: SafeErrorDiagnostic;
	exceptionType: string;
	message?: string;
	stack?: string;
	responseError?: string;
	exception: NormalizedException;
	attributes: TelemetryAttributes;
	fingerprint: string[];
};
type SentryExceptionValue = NonNullable<
	NonNullable<ErrorEvent["exception"]>["values"]
>[number];
type SentryStackFrame = NonNullable<
	NonNullable<SentryExceptionValue["stacktrace"]>["frames"]
>[number];
type SentryContext = { kind: FailureKind } & TelemetryAttributes & {
		"hevy.api.response_error"?: string;
	};

export type TelemetryAttributeValue = string | number | boolean;
export type TelemetryAttributes = Record<string, TelemetryAttributeValue>;

export type FailureKind =
	| "api"
	| "discovery"
	| "lifecycle"
	| "process"
	| "protocol"
	| "prompt"
	| "sdk"
	| "tool";

export interface FailureContext {
	readonly kind: FailureKind;
	readonly attributes?: TelemetryAttributes;
	readonly expected?: boolean;
	readonly span?: Span;
}

export interface NormalizedFailure {
	readonly diagnostic: SafeErrorDiagnostic;
	readonly exceptionType: string;
	readonly message?: string;
	readonly stack?: string;
	readonly responseError?: string;
	readonly exception: {
		readonly name: string;
		readonly message?: string;
		readonly stack?: string;
	};
	readonly attributes: TelemetryAttributes;
	readonly fingerprint: readonly string[];
}

export interface FailureReceipt {
	readonly diagnosticId?: string;
	readonly eventId?: string;
	readonly traceId?: string;
	readonly spanId?: string;
}

const MAX_ATTRIBUTE_LENGTH = 256;
const MAX_MESSAGE_LENGTH = 2_048;
const MAX_STACK_LENGTH = 16_384;
const SAFE_TAG_PREFIXES = [
	"error.",
	"exception.",
	"hevy.",
	"http.",
	"mcp.",
	"otel.",
	"service.",
] as const;
const TELEMETRY_ENABLED = process.env.HEVY_MCP_TELEMETRY !== "0";
const DIAGNOSTIC_DETAILS_ENABLED =
	process.env.HEVY_MCP_TELEMETRY_DIAGNOSTICS !== "0";

function isObject<T>(value: T): value is T & object {
	return z.object({}).passthrough().safeParse(value).success;
}

function isString<T>(value: T): value is T & string {
	return z.string().safeParse(value).success;
}

function isNumber<T>(value: T): value is T & number {
	return z.number().safeParse(value).success;
}

function isBoolean<T>(value: T): value is T & boolean {
	return z.boolean().safeParse(value).success;
}

function truncate(value: string, length: number): string {
	return value.length > length ? `${value.slice(0, length - 1)}…` : value;
}

function escapeRegExp(value: string): string {
	return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function removeHomePath(value: string): string {
	const home = process.env.HOME?.trim();
	const withConfiguredHome = home
		? value.replace(new RegExp(escapeRegExp(home), "g"), "~")
		: value;
	return withConfiguredHome.replace(/\/(?:Users|home)\/[^/\s]+/g, "~");
}

const EMAIL = /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi;

function removeControlCharacters(value: string): string {
	let output = "";
	let inEscapeSequence = false;
	for (const character of value) {
		const codePoint = character.codePointAt(0) ?? 0;
		if (inEscapeSequence) {
			if (codePoint >= 0x40 && codePoint <= 0x7e) {
				inEscapeSequence = false;
			}
			continue;
		}
		if (codePoint === 0x1b) {
			inEscapeSequence = true;
			continue;
		}
		if (
			codePoint <= 0x1f &&
			codePoint !== 0x09 &&
			codePoint !== 0x0a &&
			codePoint !== 0x0d
		) {
			continue;
		}
		if (codePoint === 0x7f) continue;
		output += character;
	}
	return output;
}

/** Remove common credentials and URL payloads without inspecting object fields. */
export function sanitizeDiagnosticText(
	value: string,
	maxLength = MAX_MESSAGE_LENGTH,
): string {
	const withoutControlCharacters = removeControlCharacters(value);
	const withoutSecrets = withoutControlCharacters
		.replace(/\bBearer\s+[^\s,;]+/gi, "Bearer [REDACTED]")
		.replace(
			/\b(api[-_ ]?key|authorization|password|secret|token)\s*[:=]\s*(?:"[^"]*"|'[^']*'|[^\s,;]+)/gi,
			"$1=[REDACTED]",
		)
		.replace(EMAIL, "[EMAIL_REDACTED]")
		.replace(/\bhttps?:\/\/[^\s)<>]+/gi, "[URL]");
	return truncate(removeHomePath(withoutSecrets).trim(), maxLength);
}

function sanitizeAttributeValue(
	_key: string,
	value: TelemetryAttributeValue,
): TelemetryAttributeValue {
	if (!isString(value)) return value;
	return sanitizeDiagnosticText(value, MAX_ATTRIBUTE_LENGTH);
}

function copyAttributes(
	attributes: TelemetryAttributes | undefined,
): TelemetryAttributes {
	if (!attributes) return {};
	const output: TelemetryAttributes = {};
	for (const [rawKey, rawValue] of Object.entries(attributes)) {
		const key = truncate(rawKey, 128);
		if (
			!key ||
			!SAFE_TAG_PREFIXES.some((prefix) => key.startsWith(prefix)) ||
			(isNumber(rawValue) && !Number.isFinite(rawValue))
		) {
			continue;
		}
		output[key] = sanitizeAttributeValue(key, rawValue);
	}
	return output;
}

type ExceptionText = {
	message?: string;
	stack?: string;
};

type TraceContext = {
	traceId?: string;
	spanId?: string;
};

function getExceptionText<T>(error: T): ExceptionText {
	if (!(error instanceof Error)) return {};
	const text: ExceptionText = {};
	if (error.message) text.message = error.message;
	if (error.stack) text.stack = error.stack;
	return text;
}

function getTraceContext(span: Span | undefined): TraceContext {
	try {
		const spanContext = span?.spanContext();
		if (!spanContext || !spanContext.traceId || !spanContext.spanId) {
			return {};
		}
		return { traceId: spanContext.traceId, spanId: spanContext.spanId };
	} catch {
		return {};
	}
}

function getFingerprint(
	kind: FailureKind,
	attributes: TelemetryAttributes,
	diagnostic: SafeErrorDiagnostic,
): string[] {
	const toolName =
		attributes["mcp.tool.name"] ?? attributes["mcp.prompt.name"] ?? "none";
	const exceptionType = String(attributes["error.type"] ?? "UNKNOWN_ERROR");
	const errorCategory = attributes["error.category"]
		? String(attributes["error.category"])
		: String(diagnostic.category);
	return [
		"mcp",
		kind,
		String(toolName),
		exceptionType,
		errorCategory,
		String(
			attributes["error.code"] ??
				attributes["http.response.status_code"] ??
				"none",
		),
	];
}

function addErrorAttributes(
	attributes: TelemetryAttributes,
	diagnostic: SafeErrorDiagnostic,
	expected: boolean | undefined,
): void {
	if (expected) attributes["error.expected"] = true;
	attributes["error.category"] ??= diagnostic.category;
	if (diagnostic.code) attributes["error.code"] ??= diagnostic.code;
}

function addHttpAttributes(
	attributes: TelemetryAttributes,
	diagnostic: SafeErrorDiagnostic,
): void {
	if (diagnostic.status !== undefined) {
		attributes["http.response.status_code"] ??= diagnostic.status;
	}
	if (diagnostic.method)
		attributes["http.request.method"] ??= diagnostic.method;
	if (diagnostic.endpoint)
		attributes["hevy.api.endpoint"] ??= diagnostic.endpoint;
}

function addExecutionAttributes(
	attributes: TelemetryAttributes,
	diagnostic: SafeErrorDiagnostic,
): void {
	if (diagnostic.outcome) attributes["hevy.api.outcome"] ??= diagnostic.outcome;
	if (diagnostic.phase) attributes["hevy.api.phase"] ??= diagnostic.phase;
	if (diagnostic.operation_safety) {
		attributes["hevy.api.operation_safety"] ??= diagnostic.operation_safety;
	}
	if (diagnostic.commit_state) {
		attributes["hevy.api.commit_state"] ??= diagnostic.commit_state;
	}
	if (diagnostic.safe_to_retry !== undefined) {
		attributes["hevy.api.safe_to_retry"] ??= diagnostic.safe_to_retry;
	}
}

export function normalizeFailure<T>(
	error: T,
	context: FailureContext,
): NormalizedFailure {
	const diagnostic = createSafeErrorDiagnostic(error);
	const attributes = copyAttributes(context.attributes);
	const exceptionType = diagnostic.category;
	const text = getExceptionText(error);
	const message =
		DIAGNOSTIC_DETAILS_ENABLED && text.message
			? sanitizeDiagnosticText(text.message)
			: undefined;
	const stack =
		DIAGNOSTIC_DETAILS_ENABLED && text.stack
			? sanitizeDiagnosticText(text.stack, MAX_STACK_LENGTH)
			: undefined;
	const responseError =
		DIAGNOSTIC_DETAILS_ENABLED && isHevyHttpError(error) && error.responseError
			? sanitizeDiagnosticText(error.responseError, MAX_ATTRIBUTE_LENGTH)
			: undefined;

	attributes["exception.type"] = exceptionType;
	addErrorAttributes(attributes, diagnostic, context.expected);
	addHttpAttributes(attributes, diagnostic);
	addExecutionAttributes(attributes, diagnostic);

	const normalizedException: NormalizedException = {
		name: exceptionType,
	};
	const normalized: NormalizedFailureDraft = {
		diagnostic,
		exceptionType,
		exception: normalizedException,
		attributes,
		fingerprint: getFingerprint(context.kind, attributes, diagnostic),
	};
	if (message) {
		normalized.message = message;
		normalized.exception.message = message;
	}
	if (stack) {
		normalized.stack = stack;
		normalized.exception.stack = stack;
	}
	if (responseError) normalized.responseError = responseError;
	return normalized as NormalizedFailure;
}

function sanitizeContext<T>(value: T): TelemetryAttributes {
	if (!isObject(value)) return {};
	const output: TelemetryAttributes = {};
	for (const [key, rawValue] of Object.entries(value).slice(0, 32)) {
		if (
			key !== "kind" &&
			!SAFE_TAG_PREFIXES.some((prefix) => key.startsWith(prefix))
		) {
			continue;
		}
		if (!isString(rawValue) && !isNumber(rawValue) && !isBoolean(rawValue)) {
			continue;
		}
		if (isNumber(rawValue) && !Number.isFinite(rawValue)) {
			continue;
		}
		output[truncate(key, 128)] = sanitizeAttributeValue(key, rawValue);
	}
	return output;
}

function sanitizeSentryTags(tags: ErrorEvent["tags"]): ErrorEvent["tags"] {
	if (!tags) return undefined;
	const output: NonNullable<ErrorEvent["tags"]> = {};
	for (const [key, value] of Object.entries(tags)) {
		if (!SAFE_TAG_PREFIXES.some((prefix) => key.startsWith(prefix))) continue;
		if (!isString(value) && !isNumber(value) && !isBoolean(value)) {
			continue;
		}
		output[truncate(key, 128)] = isString(value)
			? sanitizeDiagnosticText(value, MAX_ATTRIBUTE_LENGTH)
			: value;
	}
	return output;
}

function normalizeStackFilename(value: string): string {
	const sanitized = sanitizeDiagnosticText(value, MAX_ATTRIBUTE_LENGTH);
	const distMarker = sanitized.lastIndexOf("/dist/");
	return distMarker >= 0
		? `~${sanitized.slice(distMarker)}`
		: removeHomePath(sanitized);
}

function sanitizeSentryExceptionValues(
	event: ErrorEvent,
): ErrorEvent["exception"] {
	const values = event.exception?.values;
	if (!values) return undefined;
	return {
		values: values.map((value) => {
			const safeValue: Mutable<SentryExceptionValue> = {};
			if (value.type)
				safeValue.type = sanitizeDiagnosticText(
					value.type,
					MAX_ATTRIBUTE_LENGTH,
				);
			if (value.value)
				safeValue.value = sanitizeDiagnosticText(
					value.value,
					MAX_MESSAGE_LENGTH,
				);
			if (value.stacktrace) {
				safeValue.stacktrace = {
					frames: value.stacktrace.frames?.map((frame) => {
						const safeFrame: Mutable<SentryStackFrame> = {};
						if (frame.filename)
							safeFrame.filename = normalizeStackFilename(frame.filename);
						if (frame.function)
							safeFrame.function = sanitizeDiagnosticText(
								frame.function,
								MAX_ATTRIBUTE_LENGTH,
							);
						if (isNumber(frame.lineno)) safeFrame.lineno = frame.lineno;
						if (isNumber(frame.colno)) safeFrame.colno = frame.colno;
						if (isBoolean(frame.in_app)) safeFrame.in_app = frame.in_app;
						return safeFrame;
					}),
				};
			}
			return safeValue;
		}),
	};
}

/** Final Sentry-side safety net for SDK-generated event fields and integrations. */
export function sanitizeSentryEvent(
	event: ErrorEvent,
	_hint?: EventHint,
): ErrorEvent {
	const sanitized: ErrorEvent = {
		...event,
		request: undefined,
		user: undefined,
		server_name: undefined,
		breadcrumbs: undefined,
		extra: undefined,
		logentry: undefined,
		threads: undefined,
		sdkProcessingMetadata: undefined,
		contexts: event.contexts?.mcp
			? { mcp: sanitizeContext(event.contexts.mcp) }
			: undefined,
		tags: sanitizeSentryTags(event.tags),
		exception: sanitizeSentryExceptionValues(event),
		spans: undefined,
	};
	if (event.message)
		sanitized.message = sanitizeDiagnosticText(
			event.message,
			MAX_MESSAGE_LENGTH,
		);
	return sanitized;
}

function createSentryError(record: NormalizedFailure): Error {
	const error = new Error(record.message ?? record.exceptionType);
	error.name = record.exceptionType;
	if (record.stack) error.stack = record.stack;
	return error;
}

function setSpanAttributes(span: Span, attributes: TelemetryAttributes): void {
	try {
		span.setAttributes(attributes);
	} catch {
		// Telemetry must never alter application behavior.
	}
}

const reportedErrors = new WeakSet<object>();
const diagnosticIds = new WeakMap<object, string>();

function getDiagnosticId<T>(error: T): string | undefined {
	if (isObject(error)) {
		const existing = diagnosticIds.get(error);
		if (existing) return existing;
	}
	try {
		const generated = randomUUID();
		if (isObject(error)) diagnosticIds.set(error, generated);
		return generated;
	} catch {
		return undefined;
	}
}

function hasReportedError<T>(error: T): boolean {
	if (!isObject(error)) return false;
	if (reportedErrors.has(error)) return true;
	reportedErrors.add(error);
	return false;
}

export function captureFailure<T>(
	error: T,
	context: FailureContext,
): FailureReceipt | undefined {
	if (!TELEMETRY_ENABLED) return undefined;
	const span = context.span ?? trace.getActiveSpan() ?? undefined;
	const record = normalizeFailure(error, context);
	const traceContext = getTraceContext(span);
	if (traceContext.traceId) {
		record.attributes["otel.trace_id"] = traceContext.traceId;
	}
	if (traceContext.spanId) {
		record.attributes["otel.span_id"] = traceContext.spanId;
	}

	const diagnosticId = getDiagnosticId(error);
	if (diagnosticId) record.attributes["mcp.failure.id"] = diagnosticId;

	const duplicate = context.expected ? false : hasReportedError(error);
	let eventId: string | undefined;
	if (!duplicate && !context.expected) {
		try {
			eventId = Sentry.withScope((scope) => {
				for (const [key, value] of Object.entries(record.attributes)) {
					scope.setTag(key, String(value));
				}
				scope.setFingerprint([...record.fingerprint]);
				const sentryContext: SentryContext = {
					kind: context.kind,
					...record.attributes,
				};
				if (record.responseError)
					sentryContext["hevy.api.response_error"] = record.responseError;
				scope.setContext("mcp", sentryContext);
				return Sentry.captureException(createSentryError(record));
			});
		} catch {
			// Sentry failures must never affect MCP behavior.
		}
	}

	if (span) {
		try {
			if (!duplicate && !context.expected) {
				span.recordException(record.exception);
				if (record.responseError) {
					span.addEvent("mcp.failure.detail", {
						"hevy.api.response_error": record.responseError,
					});
				}
			}
			setSpanAttributes(span, record.attributes);
			if (!context.expected) {
				span.setStatus({ code: SpanStatusCode.ERROR });
			}
			if (eventId) span.setAttribute("sentry.event_id", eventId);
		} catch {
			// OTel failures must never affect MCP behavior.
		}
	}

	const receipt: Mutable<FailureReceipt> = {};
	if (diagnosticId) receipt.diagnosticId = diagnosticId;
	if (eventId) receipt.eventId = eventId;
	if (traceContext.traceId) receipt.traceId = traceContext.traceId;
	if (traceContext.spanId) receipt.spanId = traceContext.spanId;
	return receipt;
}

import type { CacheObservationMetadata, CacheObserver } from "@hevy-mcp/core";
import {
	diagnosticEndpointIdentity,
	metricEndpointIdentity,
	SAFE_OBSERVATION_CODES,
} from "@hevy-mcp/hevy-client";
import type {
	HevyClientOptions,
	HevyRequestObservation,
	HevyRequestStart,
} from "@hevy-mcp/hevy-client";
import { context, SpanStatusCode, trace, type Span } from "@opentelemetry/api";
import { debugLog } from "./debug.js";
import { apiCalls, apiDuration } from "./metrics.js";
import { bucketCount } from "./result-telemetry.js";
import {
	getCurrentMcpSessionId,
	getCurrentMcpTransport,
} from "./mcp-session-observability.js";
import { projectExecutionAttributes } from "./execution-telemetry.js";
import { tracer } from "./telemetry.js";

interface SafeErrorAttributes {
	error_category?: string;
	error_code?: string;
}

interface ApiSpanAttributes {
	[key: string]: string | number;
}

interface MetricAttributes {
	[key: string]: string | number | boolean;
}

interface DebugAttributes {
	[key: string]: string | number | boolean | null;
}

interface StringAttributes {
	[key: string]: string;
}

function safeErrorAttributes(
	observation: HevyRequestObservation,
): SafeErrorAttributes {
	if (!observation.error) return {};
	const code = observation.error.code;
	const attributes: SafeErrorAttributes = {
		error_category: observation.error.category ?? "HevyHttpError",
	};
	if (code && SAFE_OBSERVATION_CODES.has(code)) attributes.error_code = code;
	return attributes;
}

function getDiagnosticResponseError(
	observation: HevyRequestObservation,
): string | undefined {
	return process.env.HEVY_MCP_TELEMETRY_DIAGNOSTICS === "0"
		? undefined
		: observation.error?.response_error;
}

function startApiSpan(start: HevyRequestStart) {
	const sessionId = getCurrentMcpSessionId();
	const diagnosticEndpoint = diagnosticEndpointIdentity(start.endpoint);
	const attributes: ApiSpanAttributes = {
		"mcp.span.category": "api",
		"http.request.method": start.method,
		"hevy.api.retry_count_bucket": bucketCount(start.retryCount),
		"mcp.transport": getCurrentMcpTransport(),
	};
	if (diagnosticEndpoint) attributes["hevy.api.endpoint"] = diagnosticEndpoint;
	if (sessionId) attributes["mcp.session.id"] = sessionId;
	return tracer.startSpan(`hevy.api.${start.method}`, { attributes });
}
function finishApiSpan(span: Span, observation: HevyRequestObservation): void {
	const errorAttributes = safeErrorAttributes(observation);
	if (observation.status > 0) {
		span.setAttribute("http.response.status_code", observation.status);
	}
	for (const [key, value] of Object.entries(
		projectExecutionAttributes(observation),
	)) {
		span.setAttribute(key, value);
	}
	if (observation.expectedReason) {
		span.setAttribute("hevy.api.expected_reason", observation.expectedReason);
	}
	for (const [key, value] of Object.entries(errorAttributes)) {
		span.setAttribute(key, value);
	}
	span.setStatus({
		code:
			observation.outcome === "success" || observation.outcome === "expected"
				? SpanStatusCode.OK
				: SpanStatusCode.ERROR,
	});
	if (observation.outcome !== "success" && observation.outcome !== "expected") {
		const responseError = getDiagnosticResponseError(observation);
		const failureAttributes: StringAttributes = {
			"error.category": errorAttributes.error_category ?? "HevyHttpError",
		};
		if (errorAttributes.error_code)
			failureAttributes["error.code"] = errorAttributes.error_code;
		if (responseError)
			failureAttributes["hevy.api.response_error"] = responseError;
		span.addEvent("hevy.api.failure", failureAttributes);
	}
	span.end();
}

/** Node-only adapter; the Worker graph never imports telemetry or metrics. */
export function createNodeHevyClientOptions(): HevyClientOptions {
	const rawTimeout = process.env.HEVY_MCP_API_TIMEOUT;
	const parsedTimeout = rawTimeout ? Number(rawTimeout) : Number.NaN;
	const timeoutMs =
		Number.isFinite(parsedTimeout) && parsedTimeout > 0
			? Math.floor(parsedTimeout)
			: undefined;
	const options: HevyClientOptions = {
		onRequestStart(start) {
			const span = startApiSpan(start);
			return {
				run<T>(operation: () => Promise<T>) {
					return context.with(trace.setSpan(context.active(), span), operation);
				},
				finish(observation) {
					finishApiSpan(span, observation);
				},
			};
		},
		onRequestComplete(observation) {
			const retryCountBucket = bucketCount(observation.retryCount);
			const errorAttributes = safeErrorAttributes(observation);
			const responseError = getDiagnosticResponseError(observation);
			const metricEndpoint = metricEndpointIdentity(observation.endpoint);
			const diagnosticEndpoint = diagnosticEndpointIdentity(
				observation.endpoint,
			);
			const metricExecutionAttributes = projectExecutionAttributes(
				observation,
				"metric",
			);
			const metricAttributes: MetricAttributes = {
				...metricExecutionAttributes,
				transport: getCurrentMcpTransport(),
				...errorAttributes,
			};
			if (observation.expectedReason)
				metricAttributes.expected_reason = observation.expectedReason;
			apiCalls.add(1, {
				method: observation.method,
				endpoint: metricEndpoint,
				status_code: observation.status,
				retry_count_bucket: retryCountBucket,
				...metricAttributes,
			});
			apiDuration.record(observation.durationMs, {
				method: observation.method,
				endpoint: metricEndpoint,
				retry_count_bucket: retryCountBucket,
				...metricAttributes,
			});
			const debugAttributes: DebugAttributes = {
				method: observation.method,
				durationMs: observation.durationMs,
				status: observation.status || null,
				retryCountBucket,
				outcome: observation.outcome,
				...errorAttributes,
			};
			if (diagnosticEndpoint) debugAttributes.endpoint = diagnosticEndpoint;
			if (responseError) debugAttributes.response_error = responseError;
			debugLog("api_response", debugAttributes);
		},
		onRetryWait(observation) {
			const sessionId = getCurrentMcpSessionId();
			const attributes: ApiSpanAttributes = {
				"mcp.span.category": "api",
				"http.request.method": observation.method,
				"hevy.api.retry_count_bucket": bucketCount(observation.retryCount),
				"hevy.api.retry_wait_ms": Math.max(
					0,
					Math.min(5_000, observation.delayMs),
				),
			};
			if (sessionId) attributes["mcp.session.id"] = sessionId;
			const span = tracer.startSpan("hevy.api.retry_wait", { attributes });
			return { finish: () => span.end() };
		},
	};
	if (timeoutMs) options.timeoutMs = timeoutMs;
	return options;
}
export function createNodeCacheObserver(): CacheObserver {
	return {
		start(observation) {
			const sessionId = getCurrentMcpSessionId();
			const attributes: StringAttributes = {
				"mcp.span.category": "cache",
				"hevy.cache.state": observation.state,
				"mcp.transport": getCurrentMcpTransport(),
			};
			if (sessionId) attributes["mcp.session.id"] = sessionId;
			const span = tracer.startSpan(`hevy.cache.${observation.state}`, {
				attributes,
			});
			return {
				finish(metadata?: CacheObservationMetadata) {
					if (metadata?.refreshReason) {
						span.setAttribute(
							"hevy.cache.refresh_reason",
							metadata.refreshReason,
						);
					}
					if (metadata?.pageCountBucket) {
						span.setAttribute(
							"hevy.cache.page_count_bucket",
							metadata.pageCountBucket,
						);
					}
					if (metadata?.itemCountBucket) {
						span.setAttribute(
							"hevy.cache.item_count_bucket",
							metadata.itemCountBucket,
						);
					}
					span.end();
				},
			};
		},
	};
}

import * as crypto from "node:crypto";
import { AsyncLocalStorage } from "node:async_hooks";
import { sessionEnded, sessionStarted } from "./metrics.js";
import { bucketCount } from "./result-telemetry.js";
import { z } from "zod";
interface McpSessionMessage {
	readonly method?: string;
	readonly params?: unknown;
}

export const MCP_SESSION_TERMINATION_CATEGORIES = [
	"clean",
	"startup_failure",
	"connect_failure",
	"runtime_failure",
	"tool_failure",
	"unknown",
] as const;

export type McpSessionTerminationCategory =
	(typeof MCP_SESSION_TERMINATION_CATEGORIES)[number];
export type McpTransport = "stdio" | "http";

export interface McpClientMetadata {
	readonly name: string;
	readonly version: string;
	readonly protocolVersion: string;
}

export interface McpClientMetricAttributes {
	readonly [key: string]: string;
	readonly client_name: string;
	readonly client_version: string;
	readonly protocol_version: string;
	readonly transport: McpTransport;
}

export interface McpSessionContextOptions {
	readonly telemetrySessionId?: string;
	readonly generateTelemetrySessionId?: () => string;
	readonly now?: () => number;
}

export interface McpSessionContext {
	metadata: McpClientMetadata;
	startedAt: number;
	toolCalls: number;
	hadToolFailure: boolean;
	transport: McpTransport;
	/** Opaque process-local correlation ID; never derived from protocol headers. */
	telemetrySessionId: string;
}

const UNKNOWN_METADATA = "unknown";
const MAX_METADATA_LENGTH = 64;
const SAFE_METADATA_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._+:/@-]{0,63}$/u;
const contextStorage = new AsyncLocalStorage<McpSessionContext>();

/** Hex-encode bytes without relying on Buffer typings that vary across @types/node releases. */
function toHex(bytes: Uint8Array): string {
	let hex = "";
	for (const byte of bytes) hex += byte.toString(16).padStart(2, "0");
	return hex;
}

function generateFallbackTelemetrySessionId(): string {
	return `${Date.now().toString(36)}-${toHex(crypto.randomBytes(16))}`;
}

const parsedRandomUUID = z
	.function()
	.output(z.string())
	.safeParse(crypto.randomUUID);

function generateTelemetrySessionId(): string {
	return parsedRandomUUID.success
		? parsedRandomUUID.data()
		: generateFallbackTelemetrySessionId();
}
// Stdio has one process-wide connection and its parser callbacks are not
// attached to an AsyncLocalStorage scope. HTTP never uses this fallback: every
// request is explicitly run with its own session context.
let activeStdioSession: McpSessionContext | undefined;

type InitializeParams = {
	clientInfo?: ClientInfo;
	protocolVersion?: string;
};
type ClientInfo = {
	name?: string;
	version?: string;
};

function isObject(
	value: McpSessionMessage | null | undefined,
): value is McpSessionMessage {
	return z.object({}).passthrough().safeParse(value).success;
}

function normalizeMetadata(value: string | undefined): string {
	const parsed = z.string().safeParse(value);
	if (!parsed.success) return UNKNOWN_METADATA;
	const normalized = parsed.data.trim();
	if (
		normalized.length === 0 ||
		normalized.length > MAX_METADATA_LENGTH ||
		!SAFE_METADATA_PATTERN.test(normalized)
	) {
		return UNKNOWN_METADATA;
	}
	return normalized;
}

function getInitializeParams(message: McpSessionMessage): InitializeParams {
	if (!isObject(message) || !("method" in message)) return {};
	if (message.method !== "initialize") return {};
	const params = "params" in message ? message.params : undefined;
	const parsed = z
		.object({
			clientInfo: z
				.object({ name: z.string().optional(), version: z.string().optional() })
				.optional(),
			protocolVersion: z.string().optional(),
		})
		.safeParse(params);
	return parsed.success ? parsed.data : {};
}

export function extractMcpClientMetadata(
	message: McpSessionMessage,
): McpClientMetadata {
	const params = getInitializeParams(message);
	const clientInfo = params.clientInfo ?? {};
	return {
		name: normalizeMetadata(clientInfo.name),
		version: normalizeMetadata(clientInfo.version),
		protocolVersion: normalizeMetadata(params.protocolVersion),
	};
}

export function createMcpSessionContext(
	message: McpSessionMessage,
	transport: McpTransport = "stdio",
	options: McpSessionContextOptions | (() => string) = {},
): McpSessionContext {
	const parsedFunction = z.function().output(z.string()).safeParse(options);
	const normalizedOptions: McpSessionContextOptions = parsedFunction.success
		? { generateTelemetrySessionId: parsedFunction.data }
		: z
				.object({
					telemetrySessionId: z.string().optional(),
					generateTelemetrySessionId: z
						.function()
						.output(z.string())
						.optional(),
					now: z.function().output(z.number()).optional(),
				})
				.parse(options);
	return {
		metadata: extractMcpClientMetadata(message),
		startedAt: (normalizedOptions.now ?? Date.now)(),
		toolCalls: 0,
		hadToolFailure: false,
		transport,
		telemetrySessionId:
			normalizedOptions.telemetrySessionId ??
			(
				normalizedOptions.generateTelemetrySessionId ??
				generateTelemetrySessionId
			)(),
	};
}

export function runWithMcpSessionContext<T>(
	context: McpSessionContext,
	callback: () => T,
): T {
	return contextStorage.run(context, callback);
}

function getSession(): McpSessionContext | undefined {
	const scopedSession = contextStorage.getStore();
	return scopedSession ?? activeStdioSession;
}

export function getCurrentMcpSessionId(): string | undefined {
	return getSession()?.telemetrySessionId;
}

function metadataAttributes(
	metadata: McpClientMetadata,
	transport: McpTransport,
): McpClientMetricAttributes {
	return {
		client_name: metadata.name,
		client_version: metadata.version,
		protocol_version: metadata.protocolVersion,
		transport,
	};
}

function durationBucket(durationMs: number): string {
	if (durationMs < 1_000) return "<1s";
	if (durationMs < 10_000) return "1-10s";
	if (durationMs < 60_000) return "10-60s";
	if (durationMs < 300_000) return "1-5m";
	return "5m+";
}

export function recordMcpSessionStart(
	message: McpSessionMessage,
	transport: McpTransport = "stdio",
	context?: McpSessionContext,
): McpClientMetadata {
	const session = context ?? createMcpSessionContext(message, transport);
	if (session.transport === "stdio") activeStdioSession = session;
	const attributes = metadataAttributes(session.metadata, session.transport);
	sessionStarted.add(1, attributes);
	return session.metadata;
}

export function recordMcpToolInvocation(): McpClientMetricAttributes {
	const session = getSession();
	if (session) session.toolCalls += 1;
	return metadataAttributes(
		session?.metadata ?? {
			name: UNKNOWN_METADATA,
			version: UNKNOWN_METADATA,
			protocolVersion: UNKNOWN_METADATA,
		},
		session?.transport ?? "stdio",
	);
}

export function recordMcpToolFailure(): void {
	const session = getSession();
	if (session) session.hadToolFailure = true;
}

export function getCurrentMcpClientMetadata(): McpClientMetadata {
	return (
		getSession()?.metadata ?? {
			name: UNKNOWN_METADATA,
			version: UNKNOWN_METADATA,
			protocolVersion: UNKNOWN_METADATA,
		}
	);
}

export function getCurrentMcpTransport(): McpTransport {
	return getSession()?.transport ?? "stdio";
}

export function recordMcpSessionTermination(
	category: McpSessionTerminationCategory,
	context?: McpSessionContext,
): void {
	const session = context ?? getSession();
	const durationMs = session ? Math.max(0, Date.now() - session.startedAt) : 0;
	const metadata = session?.metadata ?? {
		name: UNKNOWN_METADATA,
		version: UNKNOWN_METADATA,
		protocolVersion: UNKNOWN_METADATA,
	};
	const attributes = {
		...metadataAttributes(metadata, session?.transport ?? "stdio"),
		termination_category: category,
		session_duration_bucket: durationBucket(durationMs),
		tool_calls_bucket: bucketCount(session?.toolCalls ?? 0),
	};
	sessionEnded.add(1, attributes);
	if (!context || context === activeStdioSession)
		activeStdioSession = undefined;
}

export function resolveSessionTerminationCategory(
	shutdownSucceeded: boolean,
	context?: McpSessionContext,
): McpSessionTerminationCategory {
	if (!shutdownSucceeded) return "unknown";
	return (context ?? getSession())?.hadToolFailure ? "tool_failure" : "clean";
}

