export { bucketCount } from "@hevy-mcp/core";
export type {
	ResultCountBucket,
	ToolResultTelemetry,
	ToolResultTelemetry as ToolResultSummary,
} from "@hevy-mcp/core";

import { AsyncLocalStorage } from "node:async_hooks";
import { SpanStatusCode, trace, type Span } from "@opentelemetry/api";
import type {
	JSONRPCRequest,
	McpServer,
	PerRequestMessageExtra,
} from "@modelcontextprotocol/server";
import { createSafeErrorDiagnostic, ErrorType } from "@hevy-mcp/core";
import type { NodeTransport } from "./arguments.js";
import {
	getCurrentMcpSessionId,
	getCurrentMcpTransport,
} from "./mcp-session-observability.js";
import { projectExecutionAttributes } from "./execution-telemetry.js";
import { captureFailure, tracer } from "./telemetry.js";
import { z } from "zod";

type SdkRequestHandler = (
	request: JSONRPCRequest,
	extra: PerRequestMessageExtra,
) => Promise<unknown>;

interface SdkProtocolInternals {
	_requestHandlers?: Map<string, SdkRequestHandler>;
}

interface SdkToolErrorHost {
	createToolError?: (message: string) => unknown;
	onerror?: (error: Error) => void;
}

const sdkToolErrorHostSchema = z.custom<SdkToolErrorHost>(
	(value) =>
		z.object({ createToolError: z.function() }).passthrough().safeParse(value)
			.success,
);
const sdkProtocolInternalsSchema = z.custom<SdkProtocolInternals>(
	(value) =>
		z
			.object({ _requestHandlers: z.instanceof(Map) })
			.passthrough()
			.safeParse(value).success,
);

interface ToolResultLike {
	isError?: unknown;
}

type FailureAttributes = Record<string, string | number | boolean>;
type SdkFailureKind = "protocol" | "tool_call" | "validation";
type SdkValidationKind = "input" | "output" | "tool_not_found" | "unknown";

interface SdkFailureTaxonomy {
	readonly [key: string]: { errorType: ErrorType; errorCategory: string };
}

interface SdkValidationResult {
	kind: SdkValidationKind;
	expected: boolean;
	toolName?: string;
}

type SdkFailureOptions = {
	expected?: boolean;
	validationKind?: SdkValidationKind;
};

const sdkToolNameStorage = new AsyncLocalStorage<string>();
const sdkRequestStateStorage = new AsyncLocalStorage<{
	expectedValidation?: boolean;
}>();
const SAFE_TOOL_NAME_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/u;
const SDK_FAILURE_TAXONOMY: SdkFailureTaxonomy = {
	protocol: {
		errorType: ErrorType.UNKNOWN_ERROR,
		errorCategory: "McpSdkProtocolFailure",
	},
	tool_call: {
		errorType: ErrorType.UNKNOWN_ERROR,
		errorCategory: "McpSdkToolCallFailure",
	},
	validation: {
		errorType: ErrorType.VALIDATION_ERROR,
		errorCategory: "McpSdkValidationFailure",
	},
};

function createFailureAttributes(
	error: Error | string,
	phase: "discovery" | "sdk",
	errorType: string,
	errorCategory: string,
): FailureAttributes {
	const diagnostic = createSafeErrorDiagnostic(error);
	const attributes: FailureAttributes = {
		"mcp.failure.phase": phase,
		"error.type": errorType,
		"error.category": errorCategory,
		...projectExecutionAttributes(diagnostic),
	};
	if (diagnostic.code) attributes["error.code"] = diagnostic.code;
	if (diagnostic.status !== undefined)
		attributes["http.response.status_code"] = diagnostic.status;
	if (diagnostic.method) attributes["http.request.method"] = diagnostic.method;
	if (diagnostic.endpoint)
		attributes["hevy.api.endpoint"] = diagnostic.endpoint;
	return attributes;
}

function enrichActiveSdkSpan(attributes: FailureAttributes): void {
	try {
		trace.getActiveSpan()?.setAttributes(attributes);
	} catch {
		// SDK span enrichment is best-effort and cannot affect protocol handling.
	}
}

function getSdkToolName(request: JSONRPCRequest): string {
	const parsed = z
		.object({ params: z.object({ name: z.string().optional() }).optional() })
		.safeParse(request);
	const candidate = parsed.success ? parsed.data.params?.name : undefined;
	return candidate && SAFE_TOOL_NAME_PATTERN.test(candidate)
		? candidate
		: "unknown";
}

function markSdkToolFailure(
	span: Span,
	error: Error | string,
	toolName = sdkToolNameStorage.getStore() ?? "unknown",
	kind: SdkFailureKind = "tool_call",
	options: SdkFailureOptions = {},
): void {
	const taxonomy = SDK_FAILURE_TAXONOMY[kind];
	const attributes: FailureAttributes = {
		"mcp.tool.name": toolName,
		...createFailureAttributes(
			error,
			"sdk",
			taxonomy.errorType,
			taxonomy.errorCategory,
		),
	};
	if (options.validationKind)
		attributes["mcp.validation.kind"] = options.validationKind;
	span.addEvent("mcp.tool.failure", attributes);
	span.setAttribute("error.type", taxonomy.errorType);
	captureFailure(error, {
		kind: "sdk",
		attributes,
		span,
		expected: options.expected,
	});
	if (options.expected !== true) {
		span.setStatus({ code: SpanStatusCode.ERROR });
	}
}

function installProtocolErrorTracking(
	server: { server?: { onerror?: (error: Error) => void } },
	transport: NodeTransport,
): void {
	const protocol = server.server;
	if (!protocol) return;
	const previous = protocol.onerror;
	protocol.onerror = (error) => {
		const taxonomy = SDK_FAILURE_TAXONOMY.protocol;
		const attributes = createFailureAttributes(
			error,
			"sdk",
			taxonomy.errorType,
			taxonomy.errorCategory,
		);
		const activeSpan = trace.getActiveSpan();
		const sessionId = getCurrentMcpSessionId();
		if (activeSpan) {
			activeSpan.addEvent("mcp.tool.failure", {
				"mcp.tool.name": sdkToolNameStorage.getStore() ?? "unknown",
				...attributes,
			});
			captureFailure(error, {
				kind: "protocol",
				attributes,
				span: activeSpan,
			});
		} else {
			tracer.startActiveSpan(
				"mcp.sdk.failure",
				{
					attributes: (() => {
						const spanAttributes: FailureAttributes = {
							"mcp.span.category": "protocol",
							"mcp.transport": transport,
						};
						if (sessionId) spanAttributes["mcp.session.id"] = sessionId;
						return spanAttributes;
					})(),
				},
				(span) => {
					span.addEvent("mcp.tool.failure", {
						"mcp.tool.name": "unknown",
						...attributes,
					});
					captureFailure(error, { kind: "protocol", attributes, span });
					span.end();
				},
			);
		}
		try {
			previous?.(error);
		} catch {
			// Existing SDK/Sentry handlers must not affect protocol behavior.
		}
	};
}

function classifySdkValidation(message: string): SdkValidationResult {
	const inputValidation =
		/^Input validation error: Invalid arguments for tool ([A-Za-z0-9][A-Za-z0-9._-]{0,63})(?::|$)/u.exec(
			message,
		);
	if (inputValidation) {
		return {
			kind: "input",
			expected: true,
			toolName: inputValidation[1],
		};
	}
	if (message.startsWith("Input validation error:")) {
		return { kind: "input", expected: true };
	}
	if (message.startsWith("Output validation error:")) {
		return { kind: "output", expected: false };
	}
	const missingTool =
		/^Tool ([A-Za-z0-9][A-Za-z0-9._-]{0,63}) not found$/u.exec(message);
	if (missingTool) {
		return {
			kind: "tool_not_found",
			expected: true,
			toolName: missingTool[1],
		};
	}
	return { kind: "unknown", expected: false };
}

function installValidationErrorTracking(server: McpServer): void {
	const parsedHost = sdkToolErrorHostSchema.safeParse(server);
	if (!parsedHost.success) return;
	const toolErrorHost = parsedHost.data;
	const previousCreateToolError = toolErrorHost.createToolError;
	if (!previousCreateToolError) return;
	const createToolError = previousCreateToolError.bind(server);
	toolErrorHost.createToolError = (message) => {
		const validation = classifySdkValidation(message);
		const requestState = sdkRequestStateStorage.getStore();
		if (requestState) requestState.expectedValidation = validation.expected;
		const result = createToolError(message);
		const activeSpan = trace.getActiveSpan();
		if (activeSpan) {
			markSdkToolFailure(
				activeSpan,
				new Error(
					validation.kind === "output"
						? "MCP tool output validation failed"
						: "MCP tool validation failed",
				),
				sdkToolNameStorage.getStore() ?? validation.toolName ?? "unknown",
				"validation",
				{
					expected: validation.expected,
					validationKind: validation.kind,
				},
			);
		}
		return result;
	};
}

function installInitializeEnrichment(
	handlers: Map<string, SdkRequestHandler>,
	transport: NodeTransport,
): void {
	const initializeHandler = handlers.get("initialize");
	if (!initializeHandler) return;
	handlers.set("initialize", (request, extra) => {
		enrichActiveSdkSpan({
			"mcp.span.category": "protocol",
			"mcp.transport": transport,
		});
		return initializeHandler(request, extra);
	});
}

function installToolCallTracking(
	handlers: Map<string, SdkRequestHandler>,
	transport: NodeTransport,
): void {
	const toolHandler = handlers.get("tools/call");
	if (!toolHandler) return;
	handlers.set("tools/call", (request, extra) => {
		const sessionId = getCurrentMcpSessionId();
		const toolName = getSdkToolName(request);
		const attributes: FailureAttributes = {
			"mcp.span.category": "protocol",
			"mcp.transport": transport,
			"mcp.operation.kind": "tool",
			"mcp.tool.name": toolName,
		};
		if (sessionId) attributes["mcp.session.id"] = sessionId;
		enrichActiveSdkSpan(attributes);
		return sdkToolNameStorage.run(toolName, () =>
			sdkRequestStateStorage.run({}, () =>
				tracer.startActiveSpan(
					"mcp.sdk.tools.call",
					{ attributes },
					async (span) => {
						try {
							const result = (await toolHandler(
								request,
								extra,
							)) as ToolResultLike;
							if (result?.isError === true) {
								span.setAttribute("mcp.tool.outcome", "returned_error");
								if (
									sdkRequestStateStorage.getStore()?.expectedValidation !== true
								) {
									span.setStatus({ code: SpanStatusCode.ERROR });
								}
							} else {
								span.setStatus({ code: SpanStatusCode.OK });
							}
							return result;
						} catch (error) {
							const validation =
								error instanceof Error
									? classifySdkValidation(error.message)
									: { kind: "unknown" as const, expected: false };
							if (validation.kind === "tool_not_found") {
								markSdkToolFailure(
									span,
									error instanceof Error ? error : String(error),
									toolName,
									"validation",
									{
										expected: true,
										validationKind: validation.kind,
									},
								);
							} else {
								markSdkToolFailure(
									span,
									error instanceof Error ? error : String(error),
									toolName,
								);
							}
							throw error;
						} finally {
							span.end();
						}
					},
				),
			),
		);
	});
}

function installDiscoveryTracking(
	handlers: Map<string, SdkRequestHandler>,
): void {
	const discoveryHandler = handlers.get("server/discover");
	if (!discoveryHandler) return;
	handlers.set("server/discover", (request, extra) => {
		const sessionId = getCurrentMcpSessionId();
		return tracer.startActiveSpan(
			"mcp.server.discover",
			{
				attributes: (() => {
					const attributes: FailureAttributes = {
						"mcp.span.category": "discovery",
						"mcp.transport": getCurrentMcpTransport(),
					};
					if (sessionId) attributes["mcp.session.id"] = sessionId;
					return attributes;
				})(),
			},
			async (span) => {
				try {
					const result = await discoveryHandler(request, extra);
					span.setStatus({ code: SpanStatusCode.OK });
					return result;
				} catch (error) {
					const normalizedError =
						error instanceof Error ? error : String(error);
					const attributes = createFailureAttributes(
						normalizedError,
						"discovery",
						ErrorType.UNKNOWN_ERROR,
						"McpServerDiscoveryFailure",
					);
					span.addEvent("mcp.discovery.failure", attributes);
					captureFailure(normalizedError, {
						kind: "discovery",
						attributes,
						span,
					});
					throw error;
				} finally {
					span.end();
				}
			},
		);
	});
}

export function installSdkErrorTracking(
	server: McpServer,
	transport: NodeTransport,
): void {
	installProtocolErrorTracking(server, transport);
	installValidationErrorTracking(server);
	const parsedInternals = sdkProtocolInternalsSchema.safeParse(server.server);
	if (!parsedInternals.success) return;
	const handlers = parsedInternals.data._requestHandlers;
	if (!(handlers instanceof Map)) return;
	installInitializeEnrichment(handlers, transport);
	installToolCallTracking(handlers, transport);
	installDiscoveryTracking(handlers);
}

import { ZodError, z } from "zod";
import { SpanStatusCode } from "@opentelemetry/api";
import { deserializeMessage } from "@modelcontextprotocol/server";
import type { JSONRPCMessage } from "@modelcontextprotocol/server";
import type { StdioServerTransport } from "@modelcontextprotocol/server/stdio";
import { createSafeErrorDiagnostic } from "@hevy-mcp/core";
import { stdioParseErrors } from "./metrics.js";
import { tracer } from "./telemetry.js";
import {
	getCurrentMcpSessionId,
	recordMcpSessionStart,
} from "./mcp-session-observability.js";
const UTF8_BOM = "\uFEFF";
/** Maximum escaped characters included in a malformed stdin shape preview. */
const STDIN_PARSE_PREVIEW_MAX_LENGTH = 200;
const SAFE_MCP_METHODS: SafeMcpMethods = {
	initialize: true,
	"notifications/initialized": true,
	"notifications/cancelled": true,
	ping: true,
	"tools/call": true,
	"tools/list": true,
	"resources/read": true,
	"resources/list": true,
	"prompts/get": true,
	"prompts/list": true,
};
const REDACTED_CONTENT_MARKER = "[REDACTED]";

const MAX_MALFORMED_LINES_PER_READ = 100;
const functionSchema = z.function();
const objectSchema = z.object({}).passthrough();
const stringSchema = z.string();

function isFunction<T>(value: T): value is T & ((...args: never[]) => void) {
	return functionSchema.safeParse(value).success;
}
function isObject<T>(value: T): value is T & object {
	return objectSchema.safeParse(value).success;
}
function isString<T>(value: T): value is T & string {
	return stringSchema.safeParse(value).success;
}

function isMalformedMessageError(error: Error | string): boolean {
	return error instanceof SyntaxError || error instanceof ZodError;
}

export interface StdioChunkSnapshot {
	lastChunkByteLength: number;
	lastChunkStartsWithUtf8Bom: boolean;
}

interface StdioSpanAttributes {
	[key: string]: string | number | boolean;
}

interface SafeMcpMethods {
	[key: string]: true;
}

interface StructuralPreview {
	structuralPreview: string;
	truncated: boolean;
}

interface MutableReadBuffer {
	_buffer?: Buffer;
	readMessage: () => JSONRPCMessage | null;
}

type MutableStdioServerTransport = {
	_readBuffer?: MutableReadBuffer;
	_ondata?: (chunk: Buffer) => void;
};

interface SdkPrivateStdioAdapter {
	wrapOnData: (onChunk: (chunk: Buffer) => void) => void;
	installReadMessageHook: (
		onReadLine: (line: string) => JSONRPCMessage,
	) => boolean;
}

/**
 * Adapter boundary around MCP SDK stdio internals.
 *
 * MCP SDK v1.29.0 exposes public message-level hooks but does not expose a
 * public raw-chunk hook on `StdioServerTransport`. To capture chunk metadata,
 * we currently rely on private internals (`_ondata`, `_readBuffer`, `_buffer`)
 * in this one place.
 *
 * If those internals change in a future SDK release, this adapter should fail
 * closed and preserve default transport behavior (no instrumentation patching).
 */
const mutableStdioServerTransportSchema = z.custom<MutableStdioServerTransport>(
	(value): value is MutableStdioServerTransport => isObject(value),
);

function createSdkPrivateStdioAdapter(
	transport: StdioServerTransport,
): SdkPrivateStdioAdapter {
	const mutableTransport = mutableStdioServerTransportSchema.parse(transport);

	return {
		wrapOnData(onChunk) {
			const originalOnData = mutableTransport._ondata;
			if (!isFunction(originalOnData)) {
				return;
			}

			mutableTransport._ondata = (chunk: Buffer) => {
				onChunk(chunk);
				originalOnData(chunk);
			};
		},
		installReadMessageHook(onReadLine) {
			const readBuffer = mutableTransport._readBuffer;
			if (!readBuffer || !isFunction(readBuffer.readMessage)) {
				return false;
			}
			let deferredMessage: JSONRPCMessage | null = null;

			readBuffer.readMessage = () => {
				if (deferredMessage) {
					const message = deferredMessage;
					deferredMessage = null;
					return message;
				}
				let skippedMalformedLines = 0;
				while (true) {
					const buffer = readBuffer._buffer;
					if (!buffer) {
						return null;
					}

					const index = buffer.indexOf("\n");
					if (index === -1) {
						return null;
					}

					const lineBuffer = buffer.subarray(0, index);
					readBuffer._buffer = buffer.subarray(index + 1);
					const line = lineBuffer.toString("utf8").replace(/\r$/, "");
					try {
						return onReadLine(line);
					} catch (error) {
						const normalizedError =
							error instanceof Error ? error : String(error);
						if (!isMalformedMessageError(normalizedError)) {
							throw error;
						}
						skippedMalformedLines += 1;
						if (skippedMalformedLines >= MAX_MALFORMED_LINES_PER_READ) {
							setImmediate(() => {
								const message = readBuffer.readMessage();
								if (message) deferredMessage = message;
							});
							return null;
						}
					}
				}
			};
			return true;
		},
	};
}

function hasUtf8BomPrefix(chunk: Buffer): boolean {
	return (
		chunk.length >= 3 &&
		chunk[0] === 0xef &&
		chunk[1] === 0xbb &&
		chunk[2] === 0xbf
	);
}

function parseFailurePosition(error: Error | string): number | null {
	if (!(error instanceof Error)) {
		return null;
	}

	const match = error.message.match(/position\s+(\d+)/i);
	if (!match || !match[1]) {
		return null;
	}

	const position = Number.parseInt(match[1], 10);
	return Number.isFinite(position) ? position : null;
}

function getFailureLocation(
	failurePosition: number | null,
	lineHadLeadingBom: boolean,
): string {
	if (lineHadLeadingBom) {
		return "line_start_bom";
	}
	if (failurePosition === 0) {
		return "line_start";
	}
	if (failurePosition !== null) {
		return "line_body";
	}
	return "unknown";
}

function createStructuralPreview(line: string): StructuralPreview {
	let structuralPreview = "";
	let inContentRun = false;
	let inWhitespaceRun = false;

	const append = (token: string): boolean => {
		if (
			structuralPreview.length + token.length >
			STDIN_PARSE_PREVIEW_MAX_LENGTH
		) {
			return false;
		}

		structuralPreview += token;
		return true;
	};

	for (const character of line) {
		if ('{}[]:,"'.includes(character)) {
			inContentRun = false;
			inWhitespaceRun = false;
			if (!append(character === '"' ? "\\u0022" : character)) {
				return { structuralPreview, truncated: true };
			}
			continue;
		}

		if (/\s/u.test(character)) {
			inContentRun = false;
			if (!inWhitespaceRun) {
				if (!append("\\s")) {
					return { structuralPreview, truncated: true };
				}
				inWhitespaceRun = true;
			}
			continue;
		}

		inWhitespaceRun = false;
		if (!inContentRun) {
			if (!append(REDACTED_CONTENT_MARKER)) {
				return { structuralPreview, truncated: true };
			}
			inContentRun = true;
		}
	}

	return {
		structuralPreview,
		truncated: false,
	};
}

function getSafeErrorKind(
	error: Error | string,
): "SyntaxError" | "Error" | "UnknownError" {
	if (error instanceof SyntaxError) {
		return "SyntaxError";
	}
	if (error instanceof Error) {
		return "Error";
	}
	return "UnknownError";
}

function reportStdinParseFailure(
	error: Error | string,
	line: string,
	lineByteLength: number,
	failureLocation: string,
	failurePosition: number | null,
): void {
	try {
		const errorKind = getSafeErrorKind(error);
		const { structuralPreview, truncated } = createStructuralPreview(line);
		const position = failurePosition === null ? "unknown" : failurePosition;

		console.error(
			`Failed to parse MCP stdin message: error_kind=${errorKind} line_bytes=${lineByteLength} failure_location=${failureLocation} failure_position=${position} shape_preview="${structuralPreview}" shape_preview_redacted=true shape_preview_truncated=${truncated}`,
		);
	} catch {
		// Diagnostics are best-effort and must not replace the parser error.
	}
}

export function deserializeMessageWithObservability(
	line: string,
	chunkSnapshot: StdioChunkSnapshot,
): JSONRPCMessage {
	const lineHadLeadingBom = line.startsWith(UTF8_BOM);
	const normalizedLine = lineHadLeadingBom ? line.slice(1) : line;
	const lineByteLength = Buffer.byteLength(line);
	const sessionId = getCurrentMcpSessionId();
	const attributes: StdioSpanAttributes = {
		"mcp.span.category": "protocol",
		"mcp.transport": "stdio",
		"mcp.stdio.parse.line.char_length": line.length,
		"mcp.stdio.parse.line.byte_length": lineByteLength,
		"mcp.stdio.parse.line.had_leading_bom": lineHadLeadingBom,
		"mcp.stdio.parse.line.bom_stripped": lineHadLeadingBom,
		"mcp.stdio.parse.chunk.last_byte_length": chunkSnapshot.lastChunkByteLength,
		"mcp.stdio.parse.chunk.last_had_utf8_bom":
			chunkSnapshot.lastChunkStartsWithUtf8Bom,
	};
	if (sessionId) attributes["mcp.session.id"] = sessionId;
	return tracer.startActiveSpan(
		"mcp.stdio.deserialize",
		{
			attributes,
		},
		(span) => {
			try {
				const message = deserializeMessage(normalizedLine);
				span.setStatus({ code: SpanStatusCode.OK });
				if (message && isObject(message) && "method" in message) {
					const method = message.method;
					if (isString(method) && SAFE_MCP_METHODS[method] === true) {
						span.setAttribute("mcp.method", method);
					}
					if (method === "initialize") {
						const client = recordMcpSessionStart(message);
						const sessionId = getCurrentMcpSessionId();
						if (sessionId) {
							span.setAttribute("mcp.session.id", sessionId);
						}
						span.setAttribute("mcp.client.name", client.name);
						span.setAttribute("mcp.client.version", client.version);
						span.setAttribute("mcp.protocol.version", client.protocolVersion);
					}
				}
				return message;
			} catch (error) {
				const normalizedError = error instanceof Error ? error : String(error);
				const diagnostic = createSafeErrorDiagnostic(normalizedError);
				const failurePosition = parseFailurePosition(normalizedError);
				const failureLocation = getFailureLocation(
					failurePosition,
					lineHadLeadingBom,
				);

				span.setStatus({ code: SpanStatusCode.ERROR });
				span.addEvent("mcp.stdio.parse.failure", {
					"error.category": diagnostic.category,
				});
				span.setAttribute("mcp.stdio.parse.failure.location", failureLocation);
				if (failurePosition !== null) {
					span.setAttribute(
						"mcp.stdio.parse.failure.position",
						failurePosition,
					);
				}

				stdioParseErrors.add(1, { failure_location: failureLocation });

				reportStdinParseFailure(
					error instanceof Error ? error : String(error),
					line,
					lineByteLength,
					failureLocation,
					failurePosition,
				);

				throw error;
			} finally {
				span.end();
			}
		},
	);
}

export function createInstrumentedStdioTransport<
	T extends StdioServerTransport,
>(transport: T): T {
	const privateAdapter = createSdkPrivateStdioAdapter(transport);
	let lastChunkSnapshot: StdioChunkSnapshot = {
		lastChunkByteLength: 0,
		lastChunkStartsWithUtf8Bom: false,
	};

	privateAdapter.wrapOnData((chunk) => {
		lastChunkSnapshot = {
			lastChunkByteLength: chunk.byteLength,
			lastChunkStartsWithUtf8Bom: hasUtf8BomPrefix(chunk),
		};
	});

	const didInstallReadMessageHook = privateAdapter.installReadMessageHook(
		(line) => deserializeMessageWithObservability(line, lastChunkSnapshot),
	);
	if (!didInstallReadMessageHook) {
		return transport;
	}

	return transport;
}

import { SpanStatusCode, type Span } from "@opentelemetry/api";
import { SAFE_USER_HASH_PATTERN } from "@hevy-mcp/core";
import type {
	SafeToolCompletion,
	SafeToolInvocation,
	ToolObservationScope,
	ToolObserver,
} from "@hevy-mcp/core";
import { createExecutionProjection } from "@hevy-mcp/core";
import {
	toolDuration,
	toolErrors,
	toolInvocations,
	toolOutcomes,
} from "./metrics.js";
import {
	getCurrentMcpClientMetadata,
	getCurrentMcpSessionId,
	getCurrentMcpTransport,
	recordMcpToolFailure,
	recordMcpToolInvocation,
} from "./mcp-session-observability.js";
import type { McpClientMetricAttributes } from "./mcp-session-observability.js";
import { projectExecutionAttributes } from "./execution-telemetry.js";
import { captureFailure, tracer } from "./telemetry.js";
import type { TelemetryAttributes } from "./failure-reporter.js";
import { z } from "zod";

type ToolMetricAttributes = McpClientMetricAttributes & {
	readonly tool_name: string;
};
const DISCOVERY_TOOL_NAMES = new Set(["search-routines"]);
const stringSchema = z.string();

function isString<T>(value: T): value is T & string {
	return stringSchema.safeParse(value).success;
}

const WORKFLOW_PAGINATION_RESOURCES = new Set([
	"workouts",
	"bodyMeasurements",
	"routines",
]);

function taxonomyAttributes(
	invocation: SafeToolInvocation,
): Record<string, string> {
	const taxonomy = invocation.taxonomy;
	return taxonomy
		? {
				"hevy.feature": taxonomy.feature,
				"mcp.tool.kind": taxonomy.kind,
				"mcp.tool.operation": taxonomy.operation,
			}
		: {};
}

function metricAttributes(
	invocation: SafeToolInvocation,
	clientAttributes: McpClientMetricAttributes,
): ToolMetricAttributes {
	return {
		tool_name: invocation.name,
		...taxonomyAttributes(invocation),
		...clientAttributes,
	};
}

function createAttributes(
	invocation: SafeToolInvocation,
	userHash?: string,
): TelemetryAttributes {
	const clientMetadata = getCurrentMcpClientMetadata();
	const isPrompt = invocation.kind === "prompt";
	const sessionId = getCurrentMcpSessionId();
	const attributes: TelemetryAttributes = {
		"mcp.span.category": DISCOVERY_TOOL_NAMES.has(invocation.name)
			? "discovery"
			: "tool",
		[isPrompt ? "mcp.prompt.name" : "mcp.tool.name"]: invocation.name,
		"mcp.operation.kind": invocation.kind ?? "tool",
		...taxonomyAttributes(invocation),
		"mcp.client.name": clientMetadata.name,
		"mcp.client.version": clientMetadata.version,
		"mcp.protocol.version": clientMetadata.protocolVersion,
		"mcp.transport": getCurrentMcpTransport(),
		"mcp.tool.args.key_count_bucket":
			invocation.argumentKeyCountBucket ?? "unknown",
		"mcp.tool.args.keys": invocation.argumentKeys?.join(",") ?? "",
	};
	if (userHash) attributes["user.hash"] = userHash;
	if (sessionId) attributes["mcp.session.id"] = sessionId;
	for (const key of Object.keys(invocation.argumentPresence ?? {})) {
		attributes[`mcp.tool.args.${key}.present`] = true;
	}
	for (const [key, bucket] of Object.entries(
		invocation.numericArgumentBuckets ?? {},
	)) {
		if (bucket !== undefined) {
			attributes[`mcp.tool.args.${key}.bucket`] = bucket;
		}
	}
	for (const [key, value] of Object.entries(
		invocation.booleanArguments ?? {},
	)) {
		if (value !== undefined) attributes[`mcp.tool.args.${key}`] = value;
	}
	return attributes;
}

function setResultAttributes(span: Span, completion: SafeToolCompletion): void {
	const result = completion.result;
	if (!result) return;
	span.setAttribute("mcp.tool.result.is_error", result.isError);
	span.setAttribute(
		"mcp.tool.result.has_structured_content",
		result.hasStructuredContent,
	);
	span.setAttribute(
		"mcp.tool.result.content_count_bucket",
		result.contentCountBucket,
	);
	const summary = result.summary;
	if (!summary) return;
	if (summary.itemCountBucket) {
		span.setAttribute(
			"mcp.tool.result.item_count_bucket",
			summary.itemCountBucket,
		);
	}
	if (summary.exerciseCountBucket) {
		span.setAttribute(
			"mcp.tool.result.exercise_count_bucket",
			summary.exerciseCountBucket,
		);
	}
	if (summary.setCountBucket) {
		span.setAttribute(
			"mcp.tool.result.set_count_bucket",
			summary.setCountBucket,
		);
	}
	if (summary.workflow) {
		span.setAttribute("workflow.name", summary.workflow.name);
		span.setAttribute("workflow.cache_status", summary.workflow.cacheStatus);
		span.setAttribute("workflow.items_scanned", summary.workflow.itemsScanned);
		for (const [resource, pageCount] of Object.entries(
			summary.workflow.pagination,
		)) {
			if (
				WORKFLOW_PAGINATION_RESOURCES.has(resource) &&
				Number.isSafeInteger(pageCount) &&
				pageCount >= 0
			) {
				span.setAttribute(`workflow.pagination.${resource}.pages`, pageCount);
			}
		}
	}
}

function createFailureAttributes(
	invocation: SafeToolInvocation,
	completion: SafeToolCompletion,
	errorType = completion.errorType ?? "UNKNOWN_ERROR",
): TelemetryAttributes {
	const diagnostic = completion.error;
	const execution = projectExecutionAttributes(
		createExecutionProjection(diagnostic),
	);
	const attributes: TelemetryAttributes = {
		[invocation.kind === "prompt" ? "mcp.prompt.name" : "mcp.tool.name"]:
			invocation.name,
		"error.type": errorType,
		"error.category": diagnostic?.category ?? "UnknownError",
		...execution,
	};
	if (diagnostic?.code) attributes["error.code"] = diagnostic.code;
	if (diagnostic?.status !== undefined)
		attributes["http.response.status_code"] = diagnostic.status;
	if (diagnostic?.method) attributes["http.request.method"] = diagnostic.method;
	if (diagnostic?.endpoint)
		attributes["hevy.api.endpoint"] = diagnostic.endpoint;
	return attributes;
}

function setSafeErrorAttributes(
	span: Span,
	invocation: SafeToolInvocation,
	completion: SafeToolCompletion,
): string {
	const errorType = completion.errorType ?? "UNKNOWN_ERROR";
	const attributes = createFailureAttributes(invocation, completion, errorType);
	if (completion.error) {
		span.addEvent("mcp.tool.failure", attributes);
	}
	for (const [key, value] of Object.entries(
		projectExecutionAttributes(createExecutionProjection(completion.error)),
	)) {
		span.setAttribute(key, value);
	}
	span.setAttribute("error.type", errorType);
	return errorType;
}

function bestEffort(operation: () => void): void {
	try {
		operation();
	} catch {
		// Observability failures must never alter tool behavior.
	}
}

export interface NodeToolObserverOptions {
	/** HMAC pseudonym derived from the authenticated Hevy API key. */
	readonly userHash?: string;
}

/** Node-only adapter from core's privacy-safe observation contract to OTel. */
export function createNodeToolObserver(
	options: NodeToolObserverOptions = {},
): ToolObserver {
	const userHash =
		isString(options.userHash) && SAFE_USER_HASH_PATTERN.test(options.userHash)
			? options.userHash
			: undefined;
	return {
		start(invocation): ToolObservationScope {
			const startedAt = Date.now();
			const clientAttributes = recordMcpToolInvocation();
			const metrics = metricAttributes(invocation, clientAttributes);
			bestEffort(() => toolInvocations.add(1, metrics));
			let completion: SafeToolCompletion | undefined;
			let activeSpan: Span | undefined;
			let thrownError: unknown;
			return {
				run<T>(operation: () => Promise<T>): Promise<T> {
					return tracer.startActiveSpan(
						`mcp.tool.${invocation.name}`,
						{ attributes: createAttributes(invocation, userHash) },
						async (span) => {
							activeSpan = span;
							try {
								return await operation();
							} catch (error) {
								thrownError = error;
								throw error;
							}
						},
					);
				},
				finish(nextCompletion) {
					if (completion) return;
					completion = nextCompletion;
					const durationMs = Math.max(
						0,
						nextCompletion.durationMs || Date.now() - startedAt,
					);
					const isError = nextCompletion.outcome !== "success";
					if (isError) bestEffort(recordMcpToolFailure);
					bestEffort(() =>
						toolOutcomes.add(1, {
							...metrics,
							outcome: nextCompletion.outcome,
						}),
					);
					let errorType: string | undefined;
					try {
						if (activeSpan) {
							activeSpan.setStatus({
								code:
									nextCompletion.outcome === "success" &&
									nextCompletion.result?.isError !== true
										? SpanStatusCode.OK
										: SpanStatusCode.ERROR,
							});
							activeSpan.setAttribute(
								"mcp.tool.outcome",
								nextCompletion.outcome,
							);
							setResultAttributes(activeSpan, nextCompletion);
							if (nextCompletion.outcome === "thrown_error") {
								errorType = setSafeErrorAttributes(
									activeSpan,
									invocation,
									nextCompletion,
								);
							}
							if (nextCompletion.outcome === "returned_error") {
								const execution = projectExecutionAttributes(
									nextCompletion.errorOutcome,
								);
								activeSpan.addEvent("mcp.tool.failure", {
									"mcp.tool.name": invocation.name,
									"error.type": "UNKNOWN_ERROR",
									"error.category": "McpToolReturnedError",
									"error.code": "MCP_TOOL_RETURNED_ERROR",
									...execution,
								});
								activeSpan.setAttribute("error.type", "UNKNOWN_ERROR");
								for (const [key, value] of Object.entries(execution)) {
									activeSpan.setAttribute(key, value);
								}
							}
						}
					} catch {
						// Instrumentation metadata must never alter the MCP response.
					} finally {
						if (nextCompletion.outcome === "thrown_error") {
							const error =
								thrownError ??
								new Error(nextCompletion.error?.category ?? errorType);
							bestEffort(() =>
								captureFailure(error, {
									kind: invocation.kind === "prompt" ? "prompt" : "tool",
									attributes: createFailureAttributes(
										invocation,
										nextCompletion,
										errorType,
									),
									span: activeSpan,
								}),
							);
							bestEffort(() =>
								toolErrors.add(1, {
									...metrics,
									error_type:
										errorType ?? nextCompletion.errorType ?? "UNKNOWN_ERROR",
								}),
							);
						}
						bestEffort(() =>
							toolDuration.record(durationMs, {
								...metrics,
								is_error: String(isError),
								outcome: nextCompletion.outcome,
							}),
						);
						bestEffort(() => activeSpan?.end());
						activeSpan = undefined;
					}
				},
			};
		},
	};
}

import { createHmac } from "node:crypto";

import { USER_HASH_CONTEXT, USER_HASH_LENGTH } from "@hevy-mcp/core";

/**
 * Derive the short, deterministic HMAC pseudonym shared with the Worker
 * telemetry contract without exporting or logging the caller's Hevy API key.
 */
export function createNodeUserHash(apiKey: string): string | undefined {
	if (apiKey.length === 0) return undefined;
	try {
		return createHmac("sha256", apiKey)
			.update(USER_HASH_CONTEXT, "utf8")
			.digest("hex")
			.slice(0, USER_HASH_LENGTH);
	} catch {
		// Telemetry enrichment must never make an authenticated request fail.
		return undefined;
	}
}

import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, unlink, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import semver from "semver";
import { z } from "zod";

const CACHE_TTL_MS = 24 * 60 * 60 * 1_000;
const REQUEST_TIMEOUT_MS = 3_000;
const REGISTRY_URL = "https://registry.npmjs.org";

interface UpdateCheckOptions {
	packageName: string;
	currentVersion: string;
}

interface CacheEntry {
	checkedAt: number;
	latestVersion: string;
}

const cacheEntrySchema = z.object({
	checkedAt: z.number(),
	latestVersion: z.string(),
});

interface ImmediateHandle {
	unref(): unknown;
}

interface VersionCheckDependencies {
	fetch: typeof fetch;
	readFile: typeof readFile;
	mkdir: typeof mkdir;
	writeFile: typeof writeFile;
	rename: typeof rename;
	unlink: typeof unlink;
	homedir: typeof homedir;
	randomUUID: typeof randomUUID;
	pid: number;
	now: () => number;
	env: NodeJS.ProcessEnv;
	writeStderr: (message: string) => unknown;
}

interface SchedulerDependencies {
	setImmediate: (callback: () => void) => ImmediateHandle;
	checkForUpdate: (
		options: UpdateCheckOptions,
		dependencies?: Partial<VersionCheckDependencies>,
	) => Promise<void>;
}

const defaultDependencies: VersionCheckDependencies = {
	fetch,
	readFile,
	mkdir,
	writeFile,
	rename,
	unlink,
	homedir,
	randomUUID,
	pid: process.pid,
	now: Date.now,
	env: process.env,
	writeStderr: (message) => process.stderr.write(message),
};

const defaultSchedulerDependencies: SchedulerDependencies = {
	setImmediate,
	checkForUpdate,
};

function getCachePath(dependencies: VersionCheckDependencies): string {
	const cacheRoot =
		dependencies.env.XDG_CACHE_HOME || join(dependencies.homedir(), ".cache");
	return join(cacheRoot, "hevy-mcp", "update-check.json");
}

function parseCacheEntry(value: string, now: number): CacheEntry | undefined {
	try {
		const parsed: unknown = JSON.parse(value);
		const cacheEntry = cacheEntrySchema.safeParse(parsed);
		if (!cacheEntry.success) return undefined;

		const { checkedAt, latestVersion } = cacheEntry.data;
		if (!Number.isFinite(checkedAt) || !semver.valid(latestVersion)) {
			return undefined;
		}

		const age = now - checkedAt;
		if (age < 0 || age >= CACHE_TTL_MS) {
			return undefined;
		}

		return { checkedAt, latestVersion };
	} catch {
		return undefined;
	}
}

function parseLatestVersion<T>(value: T): string | undefined {
	const parsed = z
		.object({ "dist-tags": z.unknown() })
		.passthrough()
		.safeParse(value);
	if (!parsed.success) {
		return undefined;
	}

	const distTags = parsed.data["dist-tags"];
	const parsedDistTags = z
		.object({ latest: z.unknown() })
		.passthrough()
		.safeParse(distTags);
	if (!parsedDistTags.success) return undefined;
	const latest = z.string().safeParse(parsedDistTags.data.latest).data;
	if (latest === undefined || !semver.valid(latest)) {
		return undefined;
	}

	return latest;
}

function shouldNotifyAboutUpdate(
	currentVersion: string,
	latestVersion: string,
): boolean {
	const current = semver.parse(currentVersion);
	const latest = semver.parse(latestVersion);

	if (
		!current ||
		!latest ||
		latest.prerelease.length > 0 ||
		!semver.gt(latest, current)
	) {
		return false;
	}

	if (latest.major > current.major) {
		return true;
	}

	return latest.major === current.major && latest.minor - current.minor > 2;
}

async function readFreshCachedVersion(
	cachePath: string,
	dependencies: VersionCheckDependencies,
): Promise<string | undefined> {
	try {
		const cache = await dependencies.readFile(cachePath, "utf8");
		return parseCacheEntry(cache, dependencies.now())?.latestVersion;
	} catch {
		return undefined;
	}
}

async function fetchLatestVersion(
	packageName: string,
	dependencies: VersionCheckDependencies,
): Promise<string | undefined> {
	try {
		const response = await dependencies.fetch(
			`${REGISTRY_URL}/${encodeURIComponent(packageName)}`,
			{
				headers: {
					Accept: "application/vnd.npm.install-v1+json",
				},
				signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
			},
		);
		if (!response.ok) {
			return undefined;
		}

		return parseLatestVersion(await response.json());
	} catch {
		return undefined;
	}
}

async function writeCache(
	cachePath: string,
	entry: CacheEntry,
	dependencies: VersionCheckDependencies,
): Promise<void> {
	const temporaryPath = `${cachePath}.${dependencies.pid}.${dependencies.randomUUID()}.tmp`;
	const payload = `${JSON.stringify(entry)}\n`;

	try {
		await dependencies.mkdir(dirname(cachePath), { recursive: true });
		await dependencies.writeFile(temporaryPath, payload, "utf8");
	} catch {
		try {
			await dependencies.unlink(temporaryPath);
		} catch {
			// Cache cleanup failures are non-fatal.
		}
		return;
	}

	try {
		await dependencies.rename(temporaryPath, cachePath);
		return;
	} catch {
		try {
			await dependencies.writeFile(cachePath, payload, "utf8");
		} catch {
			// Cache writes are deliberately non-fatal.
		}
	}

	try {
		await dependencies.unlink(temporaryPath);
	} catch {
		// Cache cleanup failures are non-fatal.
	}
}

export async function checkForUpdate(
	options: UpdateCheckOptions,
	overrides: Partial<VersionCheckDependencies> = {},
): Promise<void> {
	try {
		if (!semver.valid(options.currentVersion)) {
			return;
		}

		const dependencies = { ...defaultDependencies, ...overrides };
		const cachePath = getCachePath(dependencies);
		let latestVersion = await readFreshCachedVersion(cachePath, dependencies);

		if (!latestVersion) {
			latestVersion = await fetchLatestVersion(
				options.packageName,
				dependencies,
			);
			if (!latestVersion) {
				return;
			}

			await writeCache(
				cachePath,
				{ checkedAt: dependencies.now(), latestVersion },
				dependencies,
			);
		}

		if (shouldNotifyAboutUpdate(options.currentVersion, latestVersion)) {
			dependencies.writeStderr(
				`Update available for ${options.packageName}: current ${options.currentVersion}, latest ${latestVersion}. Notices are shown for newer major versions or when more than two minor versions behind. Update using your preferred installation method (for example, npm install -g ${options.packageName}@latest).\n`,
			);
		}
	} catch {
		// Update checks must never interfere with the MCP server lifecycle.
	}
}

export function scheduleUpdateCheck(
	options: UpdateCheckOptions,
	overrides: Partial<SchedulerDependencies> = {},
): void {
	const dependencies = { ...defaultSchedulerDependencies, ...overrides };
	const immediate = dependencies.setImmediate(() => {
		void dependencies.checkForUpdate(options).catch(() => undefined);
	});
	immediate.unref();
}

